'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["hu"]={"g-flurpruefung":["Mit tartalmaz a munka megkezdése előtti vizuális és funkcionális ellenőrzés?","A nap első küldetése előtt.","Csak az üzemanyagszintet és a jármű színét ellenőrizze.","Ellenőrizze a fékeket, a kormányművet, a villákat, a gumiabroncsokat és a biztonsági berendezéseket a használati utasítás szerint.","Végezzen próbavezetést emelt teher mellett.","A napi ellenőrzés a biztonsági szempontból lényeges alkatrészeket és funkciókat tartalmazza a használati utasítás szerint."],"g-rueckhalt":["Hogyan kezeli a meglévő vezető-visszatartó rendszert?","A targonca kötelező rögzítőrendszerrel rendelkezik.","Használja megfelelően vezetés közben.","Csak egyenetlen padlón használja.","Rövid utazásokhoz kapcsolja ki.","A tervezett utasbiztonsági rendszereket a gyártó utasításainak megfelelően kell használni; különös védelmet nyújtanak billenő események esetén."],"g-mangelmelden":["Mi vonatkozik a sérült villával rendelkező targoncára?","Ellenőrzéskor egyértelműen meggörbült fogat észlel.","Ha lehetséges, ossza el a terhelést a másik kapára.","A következő szervizig csak könnyű rakományt vezessen.","Ne használja a targoncát, és jelentse a hibát a felelős személynek.","A sérült tehermozgató berendezés meghibásodhat; A biztonsággal kapcsolatos hibák tisztázásig leállítást igényelnek."],"g-einweisung":["Különféle kezelőszervekkel rendelkező targoncára vált. Mi szükséges használat előtt?","A művelet eltér az előző járművétől.","A készülékre vonatkozó utasítások és a használati utasítás betartása.","Egy nem érintett kolléga rövid magyarázata mindig elég.","Nincs további információ, ha van targonca jogosítványa.","Az általános minősítés nem helyettesíti a ténylegesen használt készülékre vonatkozó szükséges utasításokat."],"g-anbaugeraet":["Mellékletet kell használnia. Mit ellenőriz először?","Egy új berendezés megváltoztatja a rakomány felvételének módját.","A szerelvény megfelel-e a jármű jóváhagyásának és a megengedett terhelésnek.","Csak azt, hogy az eszköz vizuálisan csatlakoztatható-e.","A melléklet felszerelhető-e dokumentáció nélkül.","A tartozékok megváltoztathatják a fennmaradó teherbírást és a terhelési középpontot; A jóváhagyásokat és a terhelhetőségi információkat ellenőrizni kell."],"g-diagramm":["Miért van szükség a terhelhetőségi diagramra?","Nehéz teher van jelen, a súlypont messze kifelé esik.","A legrövidebb útvonal meghatározása.","Az emelési magasságtól és a teherközépponttól függően megengedhető maximális terhelés felmérése.","A tartály kapacitásának meghatározásához.","A megengedett terhelések többek között a rakomány középpontjának távolságától és emelési magasságától függenek."],"g-lastschwerpunkt":["Mi történik jellemzően, ha a súlypont tovább mozdul előre?","A villák előtt messzire kinyúlik egy hosszú teher.","A megengedett teherbírás csökkenhet.","A teherbíró képesség folyamatosan növekszik.","A távolság nincs hatással a billenési nyomatékra.","A teherközépponttól való nagyobb távolság növeli a billenési nyomatékot és csökkentheti a megengedett teherbírást."],"g-gabelabstand":["Hogyan vegyenek fel a villák egy megfelelő raklapot?","Egyenletesen megrakott raklapot szeretne felvenni.","A fogakkal a lehető legközelebb és csak az egyik sarkon.","Olyan nagy távolságra, hogy a raklap oldalra billen.","Megfelelő fogtávolsággal és elegendő futóművel és támasztófelülettel.","A rakományt biztonságosan és a lehető legegyenletesebben kell megtámasztani a villákon."],"g-schieflast":["Egy rakomány instabilan van egymásra rakva. Mi a helyes?","A kartondobozok felemeléskor leeshetnek.","Kezdje lassan; a töltés stabilizálja magát.","Mielőtt felveszi a rakományt, megfelelően rögzítse vagy szerelje össze.","Emelje fel a terhet a fejmagasság fölé, hogy ne akadályozza.","A laza vagy instabil rakomány leeshet, és veszélyeztetheti az embereket; először hajtsa végre a biztonsági intézkedéseket."],"g-personen":["Fel lehet-e emelni egy embert a közönséges villákon?","Egy kolléga el akar érni egy lámpát.","Igen, ha a kolléga sisakot visel.","Nem, csak a kijelölt és engedélyezett létesítményeket használhatják az emberek speciális követelményeknek megfelelően.","Igen, ha csak egy kis magasságot közelítünk meg.","A normál villák nem személyes munkaállványok; Az emberek szállítására és emelésére speciális követelmények vonatkoznak."],"g-transporthoehe":["Hogyan szoktál raklapot szállítani?","Az út tiszta és vízszintes.","Csak a szükséges mértékben és a használati utasításnak megfelelően emelt teher mellett.","A lehető legmagasabbra emelve a terhet, hogy jobban látható legyen.","Erősen előredöntött emelőoszlopnál, függetlenül a terheléstől.","Az alacsony szállítási helyzet csökkenti a felborulás és az ütközések kockázatát; A készülék használati utasítása a meghatározó."],"g-kurvenfahrt":["Miért veszélyes a gyors kanyarodás targoncával?","Gyorsan le szeretne hagyni egy keskeny ösvényről.","Mert gyorsabban lemeríti az akkumulátort.","Mert a targonca automatikusan jobban kormányoz.","Mivel az oldalirányú erők befolyásolják a stabilitást, és felboruláshoz vezethetnek.","Kanyarodáskor további erők lépnek működésbe; a sebességet a terheléshez és a körülményekhez kell igazítani."],"g-ladebruecke":["Mit kell ellenőrizni, mielőtt felhajt egy rakodóhídra?","Teherautóval kellene vezetni.","Csak azt, hogy az ösvény elég szélesnek tűnik-e.","Terhelhetőség, biztos alátámasztás és váltás elleni védelem, valamint a jármű rögzítése.","Csak hogy be van-e kapcsolva a világítás.","A rakodóhidakat és a járműveket elmozdulás ellen biztosítani kell, és alkalmasnak kell lenni a terhelésre."],"g-fussgaenger":["Hogyan viselkedik egy zavaros kereszteződésben a gyalogosokkal?","A vizuális kapcsolatok korlátozottak.","Vezessen megfelelő sebességgel, ha szükséges, álljon meg és biztosítsa a biztonságos kilátást.","Mindig tartson fenn elsőbbséget teherhordáskor.","Csak dudálj és vezess tovább.","A gyalogosoknak különleges védelmi szükségleteik vannak; A sebességet, a láthatóságot és a kommunikációt a forgalmi útvonalhoz kell igazítani."],"g-batterieladen":["Mire kell különösen figyelni a meghajtó akkumulátorának töltésekor?","Akkumulátortöltő állomást használnak.","A töltési hely a gyártó utasításaitól függetlenül választható.","A nyílt láng használata addig megengedett, amíg a targonca álló helyzetben van.","Megfelelő rakodótér, megfelelő szellőzés és a gyártó specifikációi, valamint tűz- és robbanásvédelem.","Töltés közben elektromos energia, gázok és vegyszerek okozhatnak veszélyeket; az előírt védőintézkedéseket be kell tartani."],"h-beauftragt":["Milyen feltételek mellett üzemeltethet önállóan egy emelőkosárt?","Munkafelületet kell használnia a vállalatnál.","Ha rendelkezik gépjármű vezetői engedéllyel.","Ha alkalmas, a munkáltató utasította vagy képesített és megbízta.","Ha látott már munkaállványt.","A munkáltatónak gondoskodnia kell a működési követelményeknek megfelelő alkalmasságról, képesítésről és megbízásról."],"h-vorpruefung":["Mit kell ellenőrizni az emelőkosárral végzett munka megkezdése előtt?","A színpad egyik napról a másikra kint volt.","Vizuális és működési teszt a gyártó utasításai szerint, beleértve a biztonsági berendezéseket.","Csak a színpad színe és kora.","Hogy a munkaanyag már a platformon van-e.","Használat előtt ellenőrizni kell a gépet, a kezelőszerveket, a vészhelyzeti funkciókat és a látható sérüléseket a használati utasítás szerint."],"h-tragfaehigkeit":["Milyen adatok határozzák meg a munkakosár megengedett terhelését?","Két személy további eszközöket szeretne magával vinni.","Az emberek szabadon megbecsülhetik a megengedett össztömeget.","Csak a legnehezebb ember súlya számít.","Az emberekre, szerszámokra és anyagokra vonatkozó teherbírást nem szabad túllépni.","A névleges terhelés a teljes megengedett terhelésre vonatkozik, beleértve a szállított anyagokat is."],"h-untergrund":["Mit gondolsz, mielőtt felállítasz egy színpadot támasztékokkal?","Ön egy feltöltött terület közelében dolgozik.","Csak a gém elérhető közelségében.","Ellenőrizze az aljzat teherbírását és egyenletességét, valamint a megfelelő alátámasztást az utasítások szerint.","A lehető legkisebb számú kiterjesztett támasztékon.","Az elégtelen talaj vagy a nem megfelelő alátámasztás a stabilitás elvesztéséhez vezethet."],"h-wind":["Erős szél támad. Hogyan csinálod?","Egy szabadtéri színpaddal találja magát.","Tartsa be a gyártó által megadott határértékeket, és ha túllépi azokat, állítsa le a működést vagy engedje le biztonságosan a kosarat.","Nyújtsa ki a platformot, amennyire csak lehetséges, hogy stabilabb legyen.","Csak akkor reagáljon, ha laza tárgyak esnek le.","A gyártó által megengedett szélviszonyok működési határértékek; A szél veszélyes járulékos erőket hozhat létre."],"h-strom":["Egy légvezeték közelében kell dolgoznia. Mi a döntő?","Élő vonal van a munkaterületen.","A sisak helyettesíti a biztonságos távolság megtartását.","Csak szigetelje el a kosarat, és dolgozzon koordináció nélkül.","Tisztázza a veszélyes területet, és gondoskodjon a szükséges védőtávolságról vagy egyéb megfelelő intézkedésekről.","Az elektromos átvilágítás közvetlen érintkezés nélkül is lehetséges; A művelet megkezdése előtt meg kell határozni a szükséges védőintézkedéseket."],"h-notablass":["Miért kell ismerni a vészsüllyesztési eljárást?","A normál vezérlés meghibásodása lehetséges.","Annak érdekében, hogy meghibásodás esetén biztonságos mentés lehetséges legyen a készülék szerint.","Annak érdekében, hogy a készülék gyorsabban működjön normál működés közben.","A rendszeres tesztelés helyettesítésére.","A vészhelyzeti kezelőszerveket, a vészsüllyesztést és a mentési koncepciókat használat előtt ismerniük és működőképeseknek kell lenniük."],"h-gelaender":["Hogyan érhet el további magasságot a munkakosárban?","Egy montázspont nem elérhető.","Mássz fel a kosárkerítésre.","Helyezzen egy táblát a korlátra.","Használjon megfelelő munkaállványt megfelelő munkamagassággal; ne mássz fel korlátokra.","A kerítésen való felmászás vagy a rögtönzött magaslatok veszélyeztetik a leesés elleni védelmet."],"h-psaga":["Milyen követelmények vonatkoznak az egyéni leesés elleni védőfelszerelésekre?","Olyan munkaállványt használ, amelyhez biztonsági rendszer tartozik.","A kosáron kívüli rögzítési pont mindig elegendő.","Vegye figyelembe a kockázatértékelést, a gyártói információkat és a megfelelő rögzítési pontokat.","Ne használjon biztosítékot, ha a kosár korláttal rendelkezik.","Azt, hogy szükséges-e és mely egyéni védőeszköz, a kockázatértékelés, a színpadépítési és használati utasítás határozza meg."],"h-verfahren":["Mozgatható a színpad emelt emelvénnyel?","A munkahely pár méterre van.","Csak akkor, ha a modell és a működési feltételek a gyártó utasításai szerint ezt lehetővé teszik.","Mindig, amíg mindenki kitart.","Nem, soha, függetlenül a tervezéstől és a gyártó jóváhagyásától.","A felemelt helyzetben történő mozgás a készüléktől függ, és csak az engedélyezett működési feltételek mellett megengedett."],"h-kollision":["Mit kell megszervezni daruk vagy más gépek közelében végzett munka során?","A mozgó alkatrészek elérhetik a munkakosarat.","Semmi; a munkakosár mindig látható.","A munkakosarat mindig a többi gép fölé vezesse.","Koordinálja a munkaterületeket az ütközések vagy a becsípődések elkerülése érdekében.","A gép egyidejű működéséhez összehangolt munkafolyamatok és ütközések vagy elakadás elleni védelem szükséges."],"h-einstieg":["Hogyan lehet belépni vagy kilépni a munkakosárból?","A földszinten éred el a kosarat.","Mássz át a külső korláton.","A rendeltetésszerű hozzáférésen keresztül biztonságos helyen, a használati utasítás szerint.","A mellette elhelyezett létrán keresztül, kinyújtott gémmel.","A rendeltetésszerű hozzáférést és a gyártó utasításait be kell tartani; Az ellenőrizetlen mászás leesés kockázatával jár."],"h-defekt":["A vészleállító funkció nem működik. mit csinálsz?","A hibát az ellenőrzés során fedezi fel.","Ne használja a platformot, és jelentse a hibát.","Folytassa a munkát, ha a normál kezelőszervek működnek.","Ragassza fel a kapcsolót úgy, hogy senki ne működtesse.","A biztonsági berendezés meghibásodása a biztonság szempontjából lényeges hiba, és megakadályozza a biztonságos működést."],"h-sicht":["A vezetési mozgás akadály miatt nem látható. Hogyan állsz hozzá?","Mozgatni kellene egy mobil színpadot.","Lassan vezessen láthatóság nélkül.","Csak hagyatkozzon a távolságjelzőre.","Állítsa le a mozgást és biztosítsa a láthatóságot vagy a biztonságos utasításokat a kezelési útmutató szerint.","Az eljárás előtt az embereket, az akadályokat és a közlekedési útvonalakat biztonságosan fel kell mérni."],"h-rettung":["Mit foglal magában a telepítési tervezés, ha nagyobb magasságban dolgozik?","A színpadot távoli területen használják.","Csak a tervezett munkaidő.","Megfelelő mentési koncepció hozzáférhető, képzett emberekkel és vészsüllyesztési eljárásokkal.","Az a feltételezés, hogy a tűzoltóság minden problémát azonnal megold.","Hatékony mentést kell előre megszervezni, még akkor is, ha a normál ellenőrzések meghibásodnak."],"k-befaehigung":["Mi szükséges a daru önálló működtetéséhez?","Egy új alkalmazottnak kell átvennie a daruzást.","Alkalmasság és elvárt végzettség, oktatás és hozzá tartozó megbízás.","Gépjármű vezetői engedély elegendő.","Elég egyszer megnézni.","Darumunkát csak szakképzett és felhatalmazott személyek végezhetnek; Ennek része a felszerelések oktatása."],"k-funktionspruefung":["Mi szükséges a daru ellenőrzéséhez a műszak megkezdése előtt?","Ön átvesz egy beltéri darut.","Csak olvassa el a futási időt az adattáblán.","Ellenőrizze a biztonsági szempontból fontos funkciókat és a látható hibákat a kezelési útmutató szerint.","Ellenőrzés nélkül tesztelje a darut maximális terheléssel.","A kötelező üzemeltetési ellenőrzés a veszélyes hibák korai felismerését szolgálja."],"k-traglast":["Mi a jelentősége a megengedett teherbírásnak?","Egy rakományt kell felemelni.","Ez egy nem kötelező érvényű ajánlás.","Csak akkor érvényes, ha a horog teljesen be van húzva.","Az adott üzemi állapotra megengedett teherbírást nem szabad túllépni.","Bizonyos típusú daruk megengedett terhelése a sugártól, a gém helyzetétől és a fegyverzettől függhet."],"k-personen":["Mi vonatkozik a függő teher alatt álló személyekre?","A rakományt a munkaterületen mozgatják.","A veszélyes területet szabadon kell tartani; senki sem léphet a felfüggesztett teher alá.","A sisak lehetővé teszi, hogy közvetlenül alatta maradjon.","Rövid keresztezések megengedettek, ha a daru lassan halad.","A felfüggesztett rakományok leesés és zúzódás veszélyét hordozzák magukban; Az embereket távol kell tartani a veszélyes területtől."],"k-signale":["Nem látja a támadót, és ellentmondásos jeleket kap. mit csinálsz?","A kommunikáció nem egyértelmű.","Folytassa az utolsó meghajtó parancsot.","Állítsa le a mozgást, és világosan tisztázza a kommunikációt.","Tegye le a terhet gyorsabban, konzultáció nélkül.","A biztonságos rakománymozgások világos jelzéseket és egyértelmű kommunikációt igényelnek."],"k-sicht":["Ki nyújt támogatást a szállítás során, ha a darukezelő nem látja teljesen a rakomány útját?","A csarnok oszlopa eltakarja az utat.","Olyan személy, aki előzetes egyeztetés nélkül elhalad mellette.","Senki; csak a horog a fontos.","Megfelelő, oktatott személy, világosan elfogadott megértéssel.","Ha a terhelési út nem látható, megfelelő utasításra vagy más biztonságos megoldásra van szükség."],"k-ruck":["Miért kell kerülni a daru rángatózó mozgását?","Egy nehéz teher lendülni kezd.","További dinamikus feszültségeket hoznak létre, és destabilizálhatják a terhelést.","Alapvetően csökkentik az inga mozgását.","Mindig növelik a névleges teherbírást.","A gyorsító és fékező erők növelik a daru és a hevederek igénybevételét."],"k-sperrbereich":["Mit kell ellenőrizni, mielőtt rakományt lengetne egy közös területen?","Más alkalmazottak a közelben dolgoznak.","A rakomány vizuálisan illeszkedik-e a daruhoz.","A veszélyes terület biztosított-e, és nincs-e veszélyben ember.","Hogy a teher a lehető legmagasabbra vihető-e mindenki fölé.","A forgó- és teherpályáknak védtelen személyektől mentesnek kell lenniük."],"k-stuetzen":["Mi a döntő egy kitámasztós mobildaru esetében?","Egy darut helyeznek a részben feltöltött talajra.","Csak az út szélessége.","A tartólemezek színe.","Teherhordó alap, valamint alátámasztás és terheléselosztás a szerelési és gyártói utasítások szerint.","A telepítés jelentősen befolyásolja a stabilitást, különösen változó talajviszonyok mellett."],"k-wetter":["Egy széllökés a rakomány jelentős kilengését okozza. Mi a helyes?","Szabadban dolgozol.","Biztonságosan állítsa le a mozgást és tartsa be a megengedett üzemi feltételeket.","Gyorsan gyorsítsa fel a mozgást.","Folytassa a teher felemelését annak ellenére, hogy túllépi a gyártó által előírt határértékeket.","A szél és a lengő mozgások destabilizálhatják a rakományt és a darut; A jelentkezési korlátokat be kell tartani."],"k-freileitung":["Mi vonatkozik a darukra felsővezetékek közelében?","A gém vagy a rakomány megközelítheti a vonalat.","Nem vezető terhelés esetén a hézagok nem fontosak.","A munka megkezdése előtt tisztázza a veszélyes területet és a szükséges védőintézkedéseket a felelősekkel.","Csak a darukezelő saját reakciójára hagyatkozzon.","Az érintkezés és a feszültség áttörése veszélyeket rejt magában; biztonságos védőtávolságra vagy egyéb intézkedésekre van szükség."],"k-sichern":["Mit csinálsz, mielőtt elhagyod a darut?","A munka megszakad.","Hagyja, hogy a teher felfüggesztve lógjon.","Hagyja felügyelet nélkül a darut, miközben a hajtás működik.","Engedje le biztonságosan a rakományt, és rögzítse a darut a használati utasítás szerint.","A felfüggesztett terheket nem szabad ellenőrizetlenül hagyni; A darut és a rakományt biztonságosan kell leparkolni."],"k-lastanschlag":["Honnan tudod, hogy a használt heveder megfelelő-e?","A terhet emelőheveder segítségével kell felemelni.","Jelölés, teherbírás, állapot és a rögzítés típusához való alkalmasság tekintetében.","Csak az emelőpánt színe szerint.","Mert tegnap már használták.","A teherbírásnak és állapotnak megfelelőnek kell lennie, figyelembe véve a rögzítési feltételeket."],"k-stopp":["Egy személy váratlanul belép a terhelési útvonalra. mit csinálsz?","A daru jelenleg terhet mozgat.","Azonnal állítsa le biztonságosan a mozgást, és tisztítsa meg a veszélyes területet.","Csak adjon figyelmeztető jelzést, és folytassa a vezetést.","Emelje magasabbra a rakományt és hajtson át rajta.","Az embereket védeni kell a rakomány mozgásától; Közvetlen veszély esetén a mozgást le kell állítani."],"k-neuerkran":["Egy ismeretlen vezérlésű darut fog kapni. Mi a helyes?","A kezelőszervek eltérnek a korábbiaktól.","Ha gyanítja, próbálja ki a szokásos kulcsokat.","Engedje meg valaki másnak, aki nem rendelkezik képzéssel, hogy előre vezessen.","Független használat előtt kapja meg a készülékre vonatkozó szükséges utasításokat.","Még a tapasztalt darukezelőknek is ismerniük kell az alkalmazott speciális kezelőszerveket, védőeszközöket és határértékeket."],"a-kennzeichnung":["Honnan lehet tudni a heveder megengedett teherbírását?","Hevedert szeretne választani.","Az anyag illata.","A megfelelő, olvasható teherbírás-jelölésen és a gyártói információkon.","A tárolási idő hosszáról.","A megengedett teherbírást a címkézés és az üzemi feltételek határozzák meg."],"a-sichtpruefung":["Egyértelmű vágást észlel az emelőpánton. Hogyan állsz hozzá?","A zenekarnak terhet kell vinnie.","Ne használja a szalagot, és ne küldje el tesztelésre vagy elutasításra.","Fedje le a vágást szalaggal.","Csak különösen könnyű terhelésekhez használja.","A sérült textilhevederek meghibásodhatnak, és ezeket a selejtezési kritériumok szerint kell értékelni."],"a-neigungswinkel":["Mi történik, ha a hevederszálak dőlésszöge nagyobb, mint a függőleges?","Egy kétszálú akasztó jobban szétterül.","A szálerők mindig csökkennek.","A szálerők változatlanok maradnak.","A szálakban lévő erők növekednek; A megengedett szögeket és teherbírásokat be kell tartani.","A terjedés növekedésével a támasztószálra jutó húzóerő növekszik."],"a-schwerpunkt":["Miért kell ismerni a rakomány súlypontját?","A terhelés egyenetlenül épül fel.","Hogy a teher emelés közben stabil maradjon, és ne boruljon fel ellenőrizetlenül.","A hevederek színének kiválasztásához.","Hogy a rakomány gyorsabban forgatható legyen.","A kedvezőtlen rögzítési pontok vagy a súlypont helyzete felboruláshoz, megcsúszáshoz vagy lejtős lejtőhöz vezethet."],"a-kantenschutz":["Az emelőpánt az alkatrész éles éléhez támaszkodik. Mit kell tenni?","Az alkatrészt fel kell emelni.","Gyorsan emelje fel a terhet, mielőtt az öv megsérül.","Használjon megfelelő élvédelmet és ellenőrizze a rögzítés típusát.","A rakodófelületet csak ruhával tisztítsa.","Az éles élek károsíthatják a tartószálakat; a hevederfelszerelést ennek megfelelően védeni kell."],"a-haken":["Mire kell figyelni a heveder rögzítésekor?","Teherhorgot használsz.","Helyezze a hevedert a horogvég oldalára.","Tartsa folyamatosan nyitva a biztonsági fedelet.","Helyezze be a horgot rendeltetésszerűen a horog aljába, és vegye figyelembe a biztonsági berendezéseket.","A horog hegyének megengedhetetlen terhelése és a rögzítés hiánya a kiakasztáshoz vezethet."],"a-knoten":["Le lehet rövidíteni a túl hosszú emelőpántot csomóval?","A stop hossza nem passzol.","Nem; Csak megfelelő, jóváhagyott típusú hevedert vagy megfelelő rögzítőeszközt használjon.","Igen, ha a csomót nagyon szorosan meghúzzuk.","Igen, mindaddig, amíg a terhelés jelenleg álló helyzetben van.","A csomók jelentősen gyengíthetik a textilhevedereket, és nem megengedettek a hossz-beállítások rögtönzött."],"a-probehub":["Miért kell először óvatosan felemelni a terhet?","Biztonságosan szeretne szállítani.","Hogy a lehető leggyorsabban ingázhasson.","A hevederek helyzetének, stabilitásának és súlypontjának ellenőrzéséhez.","Mivel a teherbírás automatikusan növekszik.","A szabályozott első löket segít a helytelen megállások és instabil rakományhelyzetek észlelésében."],"a-lastweg":["Hol tartózkodhatnak az emberek a rakomány szállítása közben?","A rakomány mozgatása daruval történik.","Közvetlenül a teher alatt védősisakkal.","A teherre, ha kibírják.","A veszélyzónán kívül és nem függő teher alatt.","Még gondos rögzítés esetén is fennáll a veszély, hogy a rakomány leesik vagy leng."],"a-haende":["Hogyan kerüld el a zúzódásos sérüléseket az elválasztás során?","A teher megközelíti a támasztófelületet.","Kezét és lábát tartsa távol a zúzódási területtől, és használjon megfelelő segédeszközöket.","Tartsa a terhet puszta kézzel.","Álljon a teher és a fal közé a helyzet javításához.","Veszélyes becsípődési pontok keletkeznek a teher és a támasz között."],"a-vierstraenge":["Mi vonatkozik a terheléselosztásra egy négylábú felfüggesztésnél terheléskompenzáció nélkül?","Merev teher van rögzítve.","Mind a négy szál óhatatlanul ugyanannyit hordoz.","Az egyenletes eloszlás igazolása nélkül a teherbíró képesség nem használható általános becslésként négy egyforma terhelésű szálra.","Ekkor a dőlésszög irreleváns.","Merev terheléseknél egyenlőtlen pászmaterhelés lehetséges; A tervezésnél és a megengedett teherbírásnál ezt figyelembe kell venni."],"a-chemikalien":["Mi vonatkozik a vegyszerekkel érintkező textilhevederek használatára?","Ön egy ismeretlen folyadékkal dolgozik.","A szalag színe megbízhatóan mutatja tartósságát.","Minden textilszalag ellenáll minden vegyszernek.","Ellenőrizze a tartósságot és a gyártó adatait; Ne használjon nem megfelelő eszközöket.","A vegyszerek megtámadhatják a hevedereket, és észrevétlenül csökkenthetik teherbíró képességüket."],"a-aufbewahrung":["Hogyan tárolják a hevedereket használat után?","A küldetésnek vége.","Tiszta, száraz és sérülésektől védve a gyártó előírásai szerint.","Védetlen terhelés alatt a talajon ragadt.","Bármilyen éles kültéri horgon.","A megfelelő tárolás megakadályozza az idő előtti kopást és megkönnyíti a szemrevételezést."],"a-auswahl":["Mit kell különösen figyelembe venni érzékeny vagy éles szélű terhek esetén?","Egy festett gépelemet el kell helyezni.","Csak a szállítási sebesség.","Megfelelő hevederek és védőintézkedések a rakfelülethez és az élekhez.","A terheléstől függetlenül mindig ugyanaz az acélkábel.","A rögzítés típusának és anyagának meg kell felelnie a geometriának, a felületnek és a veszélynek."],"a-abstimmung":["A darukezelőnek nincs rálátása Önre. Hogyan adsz utasításokat?","Támadónak van kijelölve.","Tetszés szerint integetsz, amíg egy mozgás el nem kezdődik.","Csak hívj egyet, és menj el.","Egyértelműen egyeztetett táblákon vagy más megbízható kommunikáción keresztül.","A támadóknak és a darukezelőknek világosan kell kommunikálniuk; Ha nem egyértelmű, a mozgást le kell állítani."],"b-qualifikation":["Mire van szüksége egy személynek a hidraulikus kotrógép biztonságos üzemeltetéséhez működés közben?","Új személynek kell átvennie az építkezési munkát.","Megfelelő végzettség, készülékhez kapcsolódó oktatás és szükséges megbízás.","Csak gépkocsi vezetői engedély.","Csak egy gyors megfigyelés a műveletről.","A munkáltatónak biztosítania kell a szükséges képesítést és a kezelőt a feladatra megfelelően oktatnia."],"b-pruefung":["Mit tartalmaz a napi gépellenőrzés?","Ön átvesz egy kotrógépet.","Ellenőrizze a festék színét és az üléskárpitot.","Szemrevételezés és működési tesztek a használati utasítás szerint, például szivárgás és sérülés szempontjából.","Mozgassa a gémet teljes sebességgel, amíg meg nem áll.","A hidraulika, az alváz és a biztonsági berendezések károsodása súlyos balesetekhez vezethet."],"b-leitungen":["Mit kell tudni a föld alatti csövekről a feltárás előtt?","Árkot kellene ásni.","Csak a tervezett ásatási gödör hozzávetőleges mélysége.","A föld feletti jelölések színe elegendő.","Tisztázza a lehetséges vonalak helyét, és határozza meg a megfelelő biztonsági és feltárási intézkedéseket.","Az áram-, gáz- vagy vízvezetékek megsérülése életveszélyes következményekkel járhat."],"b-schwenkbereich":["Hogyan védi meg az embereket a kotrógép lengőterében?","A gémmel felveszed az anyagot.","Zárja le vagy biztosítsa a veszélyes területet, és tartsa távol az embereket.","Elfordítás előtt lassan mozgassa a lapátot.","Hajtson át a fejek feletti területen.","A forgó felépítmény és a munkaeszközök zúzódási és ütközési veszélyeket okoznak."],"b-boeschung":["Mi a fontos a munkagödör széle közelében végzett munka során?","A kotrógép megalapozott vagy feltöltött talajon áll.","Az ásási mélység önmagában határozza meg a megengedett elhelyezést.","Ügyeljen a perem teherbíró képességére és rögzítésére, valamint a kockázatbecslés szerint szükséges távolságokra.","Hajtson a lehető legközelebb a széléhez, hogy megtakarítsa a hatótávolságot.","Ha nincs elegendő szabad tér vagy stabil talaj, a töltés meghibásodhat, és a gép leeshet."],"b-standsicherheit":["Miért fontos a lejtő és a talaj a használat során?","Az építkezés egy lejtőn van.","A gép egyformán stabil bármilyen felületen.","A lánctalpas futóművek kizárják a borulás veszélyét.","Az egyenetlenségek és a lejtők befolyásolhatják a stabilitást; Tartsa be az alkalmazási határokat.","A stabilitás és a billenésbiztonság függ a padlótól, a felszereléstől, a rakománytól és a gép helyzetétől."],"b-wechselgeraet":["Mit kell ellenőrizni a kotrókanál gyorscsatlakozóval történő cseréje után?","Új melléklet lett telepítve.","Hogy megfelelően van-e reteszelve és rögzítve a kezelési útmutató szerint.","Csak hogy a lapát színe egyezik-e.","A hidraulika a lehető leghalkabban működik-e.","A hibás zárak a tartozékok leesését okozhatják."],"b-heben":["Mire kell figyelni, ha szabadon függő terhet emelünk kotrógéppel?","A kotrógépet emelési műveletekre használják.","Csak a szokásos ásási erő a döntő.","Vegye figyelembe a megengedett emelőterhelést, a megfelelő rögzítési pontokat és az előírt védőberendezéseket.","A teher a kanál fogaira akasztható.","Emelés csak a tervezett üzemi körülmények között, megfelelő felszereléssel megengedett."],"b-rueckwaerts":["Tolatni kell, de nem látod az utat. Mi a helyes?","A többi dolgozó a közelben van.","Óvatosan, láthatóság nélkül induljon el.","Csak dudálj és vezess tovább.","Álljon meg, biztosítsa a láthatóságot és a veszélyzónát, vagy szervezzen megfelelő utasításokat.","A tolatás nem veszélyeztetheti az embereket; a korlátozott láthatóság további intézkedéseket igényel."],"b-kabel":["A gém közel kerülhet egy felsővezetékhez. mit csinálsz?","Szoros építkezésen dolgozol.","Előzetesen tisztázza a veszélyes területet és a megfelelő védelmi intézkedéseket a felelősekkel.","Ha a gém festett, ne vegye figyelembe a vonalat.","Csak különösen gyorsan mozgassa a gémet.","Elektromos veszélyek az érintkezésből és a felvillanásból erednek; biztonsági távolságok és védőintézkedések szükségesek."],"b-verlassen":["Hogyan parkolja le a kotrógépet indulás előtt?","Tarts egy kis szünetet.","Hagyja szabadon lebegni a gémet.","Helyezze le biztonságosan a munkaeszközöket, és biztosítsa a gépet elmozdulás és jogosulatlan használat ellen.","Hagyja járni a motort és nyitva a fülkét.","A lesüllyesztett munkaeszközök és az akaratlan elmozdulás elleni védelem csökkenti a balesetveszélyt."],"b-hydraulik":["Sérült vezetéken nagy nyomás alatt lévő hidraulikaolajat észlel. Mi a helyes?","Egy vonal szivárog.","Érezze a szivárgást a kezével.","Rögzítsen egy új bilincset nyomás alatt.","Biztonságosan állítsa le a gépet, engedje le a nyomást, és végeztesse el a javítást felhatalmazott szakemberrel.","A nagy nyomású hidraulikafolyadék súlyos sérüléseket okozhat; soha ne ellenőrizze a szivárgást kézzel."],"b-unterbau":["Mi a veszélye az instabil felületeken való vezetésnek?","Eső után puha a talaj.","A gép elsüllyedhet, megcsúszhat vagy felborulhat.","A meghajtó automatikusan szélesedik.","Ez biztonságosabbá teszi a forgási tartományt.","Az elégtelen teherbírás jelentősen ronthatja a stabilitást és a vezetésbiztonságot."],"b-arbeitsgeraet":["Dolgozhat valaki emelt munkagép alatt?","Az ember irányítani akar valamit a lapát alatt.","Igen, ha a motor alapjáraton jár.","Nem, a munkaeszköz szükséges biztonságos alátámasztása és rögzítése nélkül.","Igen, ha a személy védősisakot visel.","A hidraulikus berendezések elsüllyedhetnek; A karbantartási munkákhoz biztonságos munkaeszközök szükségesek."],"b-geraeteart":["Hidraulikus kotróról kerekes rakodóra vált. Mi szükséges?","A működés és a mozgás viselkedése különbözik.","Ugyanaz a lábbeli.","Próbaút utasítások nélkül.","Az új géptípushoz szükséges képesítés vagy oktatás.","A minősítésnek meg kell egyeznie a használt gép típusával és a konkrét üzemeltetési követelményekkel."],"g-neigung":["Ön egy megrakott targoncát vezet egy emelkedőn. Mi a fontos?","Az útvonal tiszta lejtésű.","Mindig vezesse lefelé a rakományt, még akkor is, ha az nehéz.","Vezesse a rakományt lejtőn, és tartsa be az emelkedőn történő vezetésre vonatkozó használati utasításokat.","A haladási iránytól függetlenül emelje fel a villát a maximumra.","Emelkedőn és lejtőn a terhet mindig felfelé kell vinni; A járművet és a használati utasítást be kell tartani."],"g-gabelabsenken":["Miért kell leengedni a villát parkoláskor?","A targonca szünetre leparkolt.","Hogy mások a villával felkapaszkodhassanak.","Hogy a villa távolról jobban látható legyen.","Annak érdekében, hogy a teher felemelése ne jelentsen szükségtelen botlás- vagy sérülésveszélyt.","Az alacsonyabb teherfelvevő eszközök csökkentik a kiálló vagy nem biztosított villák miatti balesetveszélyt."],"g-fahrerwechsel":["Egy kolléga szeretné kölcsönkérni a targoncát. Minek kell jelen lennie?","A kolléga csak szóbeli engedélyt kapott tőled.","Rendelkeznie kell a szükséges képesítéssel és céges megbízatással.","A saját megbízása automatikusan rá is vonatkozik.","A személygépkocsi vezetői engedélye minden vállalkozáshoz elegendő.","Az önálló vezetés személyi alkalmassághoz, képzettséghez, végzettséghez és működési megbízáshoz kötött."],"g-ladungssicherung":["Egy raklap laza, egymásra rakott dobozokat tartalmaz. Mi a helyes?","Egy kartondoboz vezetés közben leeshet.","Szállítás előtt biztosítsa a rakományt elcsúszás és leesés ellen.","Csak lassan haladjon különösen egyenetlen talajon.","A laza dobozokat magasabb villaállással kompenzálja.","Az ipari targoncával történő szállítás előtt a rakománynak stabilnak és leesés ellen biztosítottnak kell lennie."],"g-bodenbelastung":["Ön előtt egy takaró korlátozott teherbíró képességgel. Hogyan dönt?","Az útvonal egy középszinten vezet át.","Csak figyeljen a teherautó súlyára rakomány nélkül.","Tisztázza a targoncák és rakományok megengedett padlóterhelését.","Hajtson lendülettel, hogy a mennyezet rövidebb ideig legyen terhelés alatt.","Ami lényeges, az a terület teljes tényleges igénybevétele, beleértve a járművet, a terhelést és a dinamikus hatásokat."],"g-verkehrswege":["Jelzett gyalogút keresztezi az útját. Mi a helyes?","A gyalogosok bármikor bejuthatnak az átkelőhelyre.","A kürttel mindig igényelheted az elsőbbséget.","Figyelem nélkül áthajthat a jelölésen.","Állítsa be a sebességet, figyeljen a gyalogosokra, és csak akkor folytassa a vezetést, ha szabad az út.","A közlekedési útvonalakat az emberekre való tekintettel kell vezetni; A figyelmeztető táblák nem helyettesítik a biztonságos kilátást és a szabad útvonalat."],"g-parkbremse":["Egy targoncával sík terepen parkolsz. Mit tartalmaz ez?","Néhány percre el szeretné hagyni a vezetőülést.","Parkoljon le, húzza be a rögzítőféket és biztosítsa az illetéktelen használat ellen.","Csak üres helyzetben hagyja a járművet.","Hagyja a villát fejmagasságban, hogy senki ne érjen hozzá.","Indulás előtt a targoncát biztonságosan meg kell állítani és biztosítani kell akaratlan elmozdulás ellen."],"g-typenschild":["Mely információk kötelező érvényűek a targoncák terhelésére vonatkozóan?","Nehéz gépet akarsz felvenni.","A becsült teherbírás a jármű mérete alapján.","A gyártó adatai a terhelési vagy teherbírási diagramban.","Az utolsó szállított raklap súlya.","A megengedett terhelést a gyártó információi határozzák meg, és többek között függ a terhelés középpontjától és az emelési magasságtól."],"g-tore":["Targoncával közelít meg egy alacsony átjárót. Mit ellenőriz?","A járművön tornyosuló rakomány van.","Biztonságosan lehetséges-e az áthaladás a teherrel és a rögzítéssel együtt.","Csak a villatartó magassága teher nélkül.","Hogy gyorsabban tud-e áthajtani a kapuzárás előtt.","Az átjárók előtt figyelembe kell venni a szabad magasságot és szélességet, valamint a rakomány és a jármű méreteit."],"g-reifen":["A napi ellenőrzés során súlyosan sérült gumiabroncsot talál. mit csinálsz?","Biztonsági szempontból lényeges sérülések láthatók az abroncson.","Lassan vezet a szokásos karbantartási időpontig.","Növeli a gumiabroncsok nyomását és folytatja a vezetést.","Ön nem veszi üzembe a járművet és nem jelenti be a kárt.","A sérült gumiabroncsok ronthatják a stabilitást és a kezelhetőséget; használat előtt tisztázni kell a hibát."],"h-absperren":["Az alkalmazottak elmennek a munkaállvány alatt. Mi szükséges?","Fennáll a leeső szerszámok veszélye.","Megfelelő védő vagy korlátozott terület a munkahely alatt.","Csak egy figyelmeztetés, amikor először elhalad mellette.","Tárolja a szerszámokat a lehető legtávolabb a kosár szélétől.","A megemelt munkaállomások alatti munkaterületet biztosítani kell a leeső alkatrészek okozta veszély ellen."],"h-werkzeuge":["Hogyan szállítja a szerszámokat a munkakosárban?","A magasságban több kis szerszámra van szükség.","Lazán helyezze őket a korlátra, hogy könnyen elérhetőek legyenek.","Tárolja és rögzítse úgy, hogy ne essen le és ne akadályozza a működést.","Rögzítse a zsebében lévő korlát külső oldalára.","A laza tárgyak leeshetnek és veszélyeztethetik az embereket; biztonságos tárolásra van szükség."],"h-abstuetzung":["Egy tartó az aknafedélen áll. Mit kell ellenőrizni?","Fel akarja emelni az emelvényt.","Csak győződjön meg arról, hogy a fedél száraz.","Hogy a terhelés biztonságosan felvehető-e azon a ponton.","Hogy a többi támaszt nem kell-e használni.","Az altalajnak és az érintkezési területeknek biztonságosan fel kell venniük a támasztóerőket; A burkolatokat külön kell értékelni."],"h-notaus":["Mikor kell használni a vészleállító berendezést?","Azonnal veszélyes mozgás következik be.","Csak a rendes műszak végén.","Akut veszélyhelyzetben történő megálláshoz a használati utasítás szerint.","A tervezett süllyesztés pótlásaként.","A vészleállítás a veszély elhárítására szolgál, nem a szokásos vezérlésre vagy normál leállításra."],"h-schraegstellung":["A tárgyasztal dőlésére figyelmeztető üzenet válaszol. How do you react?","A gép ferde felületen áll.","Alacsony munkamagasságnál figyelmen kívül hagyja a figyelmeztetést.","A figyelmeztetés ellenére Ön a legmagasabb emelési pozícióba hajt.","Megáll és biztonságos állapotba hozza a színpadot a gyártó utasításai szerint.","A dőlésre figyelmeztető jelzések nem megfelelő stabilitást jelezhetnek; további mozgások nem növelhetik a veszélyt."],"h-umgebung":["Mit kell megszervezni a közlekedési terület közelében történő felállításnál?","Vehicles can touch the stage.","Ütközés elleni védelem és megfelelő forgalomirányítás.","Fordítsa el a munkakosarat, amennyire csak lehetséges, az út fölé.","Just a warning call before you boot up.","A munkaállványokat védeni kell az úthasználókkal való ütközés ellen; the installation must be secured accordingly."],"h-ueberlast":["A kosárban lévő túlterhelés figyelmeztetés aktiválódik. mit csinálsz?","További eszközöket hívtak meg.","Nagyobb sebességgel fejezze be a munkát.","Határozza meg a megengedett kosárterhelést és kövesse a gyártó utasításait.","Switch off the warning signal permanently.","A kosár megengedett legnagyobb terhelését, beleértve az embereket és az anyagokat, nem szabad túllépni."],"h-quetschen":["Tető alá hajtod a kosarat. Melyik veszély különösen fontos?","A kosár fölött kevés hely maradt.","Beszorítás vagy zúzódás a kosár és a szerkezet között.","Hogy a motor több üzemanyagot fogyaszt.","Hogy a haladási irány mindig automatikusan megfordul.","A munkakosár feletti vagy melletti szűk helyek súlyos zúzódási sérüléseket okozhatnak."],"h-stromausfall":["A színpad nagy magasságban marad főhajtás nélkül. Mi a helyes?","A normál kosárvezérlő már nem reagál.","Biztonság nélkül mássz le a gémről.","Megvárod a műszak végét anélkül, hogy értesítenének.","Indítsa el az előkészített mentést képzett emberekkel és vészsüllyesztéssel.","Meg kell tervezni a biztonságos mentést a zavarok esetére; A képzett embereknek ismerniük kell a vészhelyzeti funkciókat."],"h-transportstellung":["Hogyan készíti el a terepet egy szállításhoz?","A munkaállványt megfelelő járműre rakják.","Állítsa a gémet és az emelőkosárt szállítási helyzetbe a kezelési útmutató szerint.","Kösse le a platformot, amennyire csak lehetséges.","Hagyja kinyújtva a támasztékokat, így több helyet foglal el.","Az előírt szállítási helyzet és rakományrögzítés a gyártó és a szállítási előírásokon alapul."],"k-bremsprobe":["Mit mutat a darufék működési tesztje használat előtt?","Szeretné biztonságosan tartani a terhet.","A fék megáll-e, és rendeltetésszerűen tartja-e a mozgást.","Csak azt, hogy működik-e az utastér világítása.","A horog képes-e automatikusan megtartani a terhet.","Használat előtt ellenőrizni kell a biztonsági funkciókat az előírásoknak megfelelően."],"k-schraegzug":["Lehet oldalra rakott terhet ferdén húzni a daruval?","A horog nincs függőlegesen a teher felett.","Igen, ha a darunak még van terhelési tartaléka.","Nem, a terheket nem szabad megengedhetetlen átlós húzással húzni.","Igen, ha a hevederek különösen rövidek.","Az átlós húzás ellenőrizetlen mozgásokat és további terhelést okozhat a darukon és a hevedereken."],"k-verhakt":["A load hangs on the substructure. Mi a helyes?","Resistance is felt when lifting.","You keep lifting until it comes away.","You move the load sideways jerkily.","Megáll, és biztonságosan eltávolítja a rögzítést vagy az eltömődést.","Az elakadt terheket nem szabad erővel elszakítani, mert elfogadhatatlan erők léphetnek fel."],"k-anzuheben":["Mit kell ellenőrizni a felfüggesztett rakomány első felemelésekor?","A rakomány néhány centiméterre felemelkedik a talajtól.","Függetlenül attól, hogy egyensúlyban van-e, és az ütközés biztonságos-e.","Hogy az ember közvetlenül a terhelés alá tudja-e helyezni magát.","Hogy a daru stabilabbá válik-e a gyors fordulástól.","A rövid vezérelt emelést a rögzítés, az egyensúly és a biztonságos rakomány viselkedésének ellenőrzésére használják."],"k-lastweg":["Hol legyen a daru rakomány szállítási útvonala?","Több munkahely is a lehetséges terhelési út alatt áll.","Lehetőleg az elfoglalt munkaállomások felett.","Tervezett, tiszta úton, embereket nem veszélyeztetve.","Mindig átlósan a legforgalmasabb területen.","A rakodási útvonalakat úgy kell megszervezni, hogy a függő teher ne veszélyeztesse az embereket."],"k-signalverlust":["Megszakad a rádiókapcsolat a marsallal. mit csinálsz?","Maga a betöltési útvonal nem látható.","Lassan folytatod a mozgást.","Kísérletileg az előző irányba lendülsz.","Addig állítod le a mozgást, amíg nincs tiszta, biztos megértés.","Ha hiányzik a kommunikáció, előfordulhat, hogy a zavaros tehermozgás nem folytatódik."],"k-haken":["The safety hook does not close reliably. Mi a helyes?","Az ellenőrzés során hibás zárás észlelhető.","A hibát a további használat előtt szakszerűen ki kell javítani.","You tie the clasp tight with a cable tie.","You only use the hook for light loads.","A teherhorgokon lévő hibás rögzítőelemek a hevederek kiakadását okozhatják, ezért ezeket meg kell javítani."],"k-zugrichtung":["Mi a fontos a teher függőleges megtámasztásához?","The load is to be lifted from a machine.","A daruhorgot a rakomány súlypontja fölé kell igazítani.","A horgot a lehető legoldalra kell helyezni.","The load must be pushed before lifting.","A terhelés középpontja felett a lehető legfüggőlegesebb erőhatás elkerüli a nem megengedett oldalirányú erőket és az ellenőrizetlen kilendülést."],"k-wartung":["Szokatlan csiszolási zaj észlelhető a darukon. Hogyan állsz hozzá?","The noise occurs when lifting.","Cover up the noise through higher speed.","Biztonságosan állítsa le a műveleteket, jelentse a hibákat és javíttassa ki azokat.","Continue working without notice until the break.","Az észrevehető változások a biztonság szempontjából lényeges károkat jelezhetnek, és ellenőrzést igényelnek."],"k-absetzen":["Mit kell garantálni a daru teher leengedésekor?","A heavy load is positioned on a surface.","A rakomány rögzítetlenül feküdhet ferde felületen.","Slings are removed while it is still floating.","A rakomány stabil, felborulás vagy elgurulás ellen biztosított.","A rakományt csak a biztonságos lerakás és a stabilitás megállapítása után szabad leengedni a függesztőszerkezetről."],"l-schwerpunkt":["Miért kell ismerni a súlypontot az ütközés előtt?","Aszimmetrikus formájú gépet kell szállítani.","Hogy a teher a lehető legkiegyensúlyozottabb maradjon emeléskor.","Hogy a hevederek tetszőleges hosszúságúak legyenek.","Hogy a megengedett teherbírás ne játsszon szerepet.","A súlypont helyzete befolyásolja a tehereloszlást és a biztonságos egyensúlyt emeléskor."],"l-etikett":["Az emelőhevederen nincs olvasható teherbírás-címke. Mi a helyes?","The marking has become unrecognizable.","Estimate the load capacity based on the color.","Ne használja az emelőhevedert, amíg alkalmasságát egyértelműen nem bizonyították.","Only use the belt once for small loads.","Suitable markings are required for slings; A megmagyarázhatatlan teherbírás kizárja a biztonságos kiválasztást."],"l-kantenschutz":["Egy éles acélperemen textilszalag húzódik. Mi szükséges?","A rakomány éles szélekkel rendelkezik.","Húzza meg a szalagot a lehető legszorosabban védelem nélkül.","Hajtsa végre az ütést gyorsabban.","Használjon megfelelő élvédelmet vagy más megfelelő rögzítőeszközt.","Az éles szélek károsíthatják vagy elvághatják a textilhevedereket; megfelelő védelem szükséges."],"l-spreizwinkel":["Hogyan befolyásolja a nagyobb dőlésszög a hevederek terhelését?","A teher felemelése két ferde kötéllel történik.","Kedvezőtlenebb szögeknél a szálakban fellépő erők növekedhetnek.","A szálerők eltűnnek.","A szögnek nincs hatása a feszültségre.","Kedvezőtlenebb ütközési szög esetén az egy szálra eső erők növekedhetnek; A terhelhetőségi táblázatokat be kell tartani."],"l-knoten":["Csomóval tetszés szerint lerövidíthető a hevederkötel?","A kötél túl hosszú a tervezett terheléshez.","Igen, a szoros csomó javítja a terhelhetőséget.","Nem, csak jóváhagyott rövidítési és rögzítési módszereket használjon.","Igen, ha a csomót szalaggal rögzítik.","A meg nem engedett csomók gyengítik a hevedereket és megváltoztatják a megengedett teherbírásukat."],"l-zeichen":["Mi vonatkozik a darut kezelő személlyel való kommunikációra?","A terhelési út részben el van takarva.","Több ember különböző jeleket ad egyszerre.","Világos, előre egyeztetett jelzéseket használnak.","A rádiódarukkal soha nincs szükség kommunikációra.","Az egyértelmű jelzések és az egyértelmű felelősség megakadályozza a veszélyes helytelen mozgásokat."],"l-sichtpruefung":["Mikor kell ellenőrizni a hevedereket, hogy nincsenek-e látható hibák?","You want to use a sling chain.","Használat előtt ügyeljen a kívülről látható sérülésekre.","Only if an accident has already happened.","Only once when first purchased.","Minden használat előtt fel kell mérni a biztonságos üzemállapotot; Visible damage precludes safe use."],"l-drehung":["A lifted load begins to rotate uncontrollably. mit csinálsz?","The load moves in the load path.","You put your hand between the load and the wall.","A teher alá helyezed magad, és ragaszkodsz hozzá.","Tartja a távolságot, és hagyja, hogy a mozgás kontrolláltan megálljon.","Az ellenőrizetlen rakománymozgások zúzódási és ütközési veszélyeket okoznak; People must leave the danger area."],"l-ablegen":["Mikor lehet a hevedereket levenni a rakományról?","A terhelést bakokra helyezik.","Ha a rakomány stabil és felborulás vagy elgurulás ellen biztosított.","Amint először érinti a talajt, helyzetétől függetlenül.","Miközben továbbra is lebeg, hogy időt takarítson meg.","A hevedereket csak biztonságos és stabil lerakás után szabad eltávolítani."],"l-ketten":["A láncheveder erősen meggörbült. mit csinálsz?","A sérülés már felemelés előtt is látható.","Tekerje be a sérült területet dróttal.","Távolítsa el a láncot a használatból, és ellenőriztesse szakemberrel.","Csak fele olyan magasra emelje a terhet.","A deformált láncszemek látható sérülések, amelyek megakadályozhatják a biztonságos használatot."],"b-einweiser":["Mi a fontos, ha a kotrógép felőli kilátás korlátozott?","Az épület egy része eltakarja a vezetési területet.","Megfelelő vizuális intézkedések vagy utasítások és egyértelmű kommunikáció.","Csak figyeld a motorháztetőt.","Haladjon át a forgó területen annak ellenére, hogy láthatatlan.","Ha a látási viszonyok korlátozottak, további szervezési és műszaki intézkedésekkel meg kell előzni a veszélyeket."],"b-aushub":["Hol lehet a kitermelt anyagot építési gödör közelében tárolni?","A gödör szélét nem szabad további kockázatnak kitenni.","Közvetlenül a szélén halmozzon fel, hogy a felhajtók szabadok maradjanak.","Tárolja kellően biztonságos távolságban és az építési terület előírásainak megfelelően.","Helyezze laza támasztékra további vizsgálat nélkül.","A kitermelt anyag a további terhelések miatt veszélyeztetheti a töltéseket és az alátámasztást; A biztonsági távolságokat be kell tartani."],"b-personen":["A kotrógép mozgása közben tartózkodhatnak emberek a hintaterületen?","Az ember pásztázás közben mérni akar.","Igen, amíg védősisakot visel.","Igen, ha a kotrógép lassan lendül.","Nem, a veszélyes területnek szabadnak kell lennie mozgás előtt.","Súlyos zúzódási és ütközési sérülések veszélye áll fenn a forgási területen; a területet szabadon kell tartani."],"b-ladung":["Hogyan szállíthat biztonságosan anyagot kerekes rakodóval?","Töltött lapáttal kell áthajtani az udvaron.","Megfelelő alacsony szállítási helyzettel és szabad úttal.","Emelt lapáttal a jobb láthatóság érdekében.","Nyitott ajtókkal és erős kormányszöggel.","A megfelelő szállítási helyzet csökkenti a borulás veszélyét és javítja a vezetési stabilitást."],"b-anbaupruefung":["Mit kell ellenőrizni a melléklet csatlakoztatása után?","Új lapát került hozzá.","Csak a fényezés tisztasága.","Biztonságos zárás és működés a használati utasítás szerint.","Csak azt, hogy a készülék ugyanúgy néz-e ki kívülről.","A gyorscsatlakozók nem megfelelő reteszelése a tartozékok akaratlan kioldásához vezethet."],"b-einstieg":["Hogyan lehet biztonságosan bejutni a kotrófülkébe?","A lépcsők eső után piszkosak.","Mássz fel a kabinba a gémen keresztül.","Egy ugrással felszállni a hernyókra.","Használja a kijelölt lépcsőket és kapaszkodókat, és tisztítsa meg a szennyezett lépcsőket.","A megfelelő emelkedők és biztonságos tartási pontok csökkentik a csúszás és leesés kockázatát."],"b-graben":["Az árok falán repedések láthatók, és omladozó. Mi a helyes?","Közvetlenül az árok mellett dolgozol.","Állítsa le a munkát, és a felelősök biztosítsák a gödört.","Az árok bezárásához egyszerűen hajtson közelebb a széléhez.","Mélyítse tovább az árkot védelem nélkül.","A repedések és a talajmozgások instabilitást jelezhetnek, és további biztonsági értékelést igényelnek."],"b-betanken":["Mire kell figyelni a földmunkagép tankolásakor?","A tank majdnem üres.","Rögzítse a motort és a gyújtóforrásokat a gyártó utasításai szerint, és kerülje a kiömlést.","Mindig töltsön utána benzint vagy gázolajat az utastérben.","Tankolás közben dohányozzon, amikor nincs szél.","Az üzemanyag kezelése során felmerülő tűz- és környezeti veszélyek megfelelő védőintézkedéseket igényelnek."],"b-laufwerk":["Miért kell rendszeresen ellenőrizni a nyomtávokat és a futóművet?","Vezetés közben szokatlan rezgéseket észlel.","Hogy a gép gyorsabban tudjon haladni.","Mivel a sérülések befolyásolhatják a biztonságos útmutatást és a stabilitást.","Mert a munkavégzés mindig megengedett szemrevételezés nélkül.","A hajtás sérülése befolyásolhatja a manőverezést, a stabilitást és a biztonságos működést."],"b-einweisen":["Mi szükséges a nyilvános gyalogosforgalom közelében végzett munkához?","A kotrógép közvetlenül a járda szélén dolgozik.","A gyalogosoknak maguknak kell áthaladniuk a hinta területén.","Csak ragassz egy táblát a lapátra.","Hatékonyan zárja le a veszélyzónát és irányítsa biztonságosan a forgalmat.","Harmadik személyek nem léphetnek be a földmunkagépek veszélyzónájába; Megfelelő sorompók és forgalomirányítás szükséges."],"g2-fahrweg":["Folyadék ömlött az útra. Hogyan állsz hozzá?","A targonca közvetlenül a csúszós területen haladna át.","Hagyja abba a vezetést, és biztosítsa vagy távolítsa el a veszélyes helyet.","A lehető leggyorsabban haladjon át a helyszínen felemelt villával.","Reménykedjünk a szárazabb gumikban, és változatlanul folytassuk a vezetést.","A szennyezett utak veszélyeztetik a stabilitást, ezért a ráhajtás előtt megfelelően rögzíteni kell."],"g2-sichtladung":["Egy magas raklap blokkolja a kilátást. Mi a helyes?","Egy raktárhoz kell vezetnie, és nem látja az útvonalat.","Emelje fel a raklapot, amíg nem látja alatta.","Csak megfelelő, biztonságos módszerekkel vezessen, például tolatással szabad kilátással.","Továbbra is közlekedhet az úton útjelző tábla vagy szabad kilátás nélkül.","A haladási iránynak és a látótávolságnak lehetővé kell tennie a közlekedési útvonal biztonságos megfigyelését; A terhelés nem helyettesítheti a szemrevételezést."],"g2-fussgaengerstop":["Közvetlenül a targonca mellett megáll egy gyalogos. mit csinálsz?","A személy a lehetséges vezetési és elfordulási tartományon belül van.","Előzze meg a gyalogost rövid gyorsítással.","Haladjon el a személy mellett felemelt teherrel.","Álljon meg, és csak biztonságos távolságban folytassa a vezetést.","Az embereknek távol kell maradniuk a veszélyes területről; Ha szükséges, az utazást meg kell szakítani."],"g2-hubmast":["Sérült hidraulikavezetéket észlel az emelőoszlopon. Mi vonatkozik rá?","A hidraulika olaj láthatóan szivárog a munkaeszközből.","Állítsa le a targoncát és jelentse a sérülést.","Kézzel ellenőrizze a szivárgást emelés közben.","Kisebb terheket csak a műszak lejártáig emeljen.","A hidraulikus sérülések ellenőrizetlen mozgásokhoz vezethetnek; a biztonságos használat a vizsgálatig nem garantált."],"g2-lagerregal":["Egy raklapot szeretne polcon tárolni. Mit ellenőriz először?","A polc szintje magas és a teherbírást fenn kell tartani.","A lehető leggyorsabban nyomja a raklapot a polcra.","Ellenőrizze a polcrekesz, a rakomány súlya és a szabad tárolóhely alkalmasságát.","A teljes súlyt kizárólag a dobozok száma alapján becsülje meg.","A polcoknak és a teherhordó berendezéseknek meg kell felelniük a rakomány és a tárolás helyzetének."],"g2-batterieschaden":["A targonca akkumulátora kívülről sérült. Mi a helyes?","Betöltés előtt repedéseket vagy szokatlan folyadékot észlel.","Fedje le a sérülést ragasztószalaggal, és azonnal töltse fel.","Hagyja, hogy egy másik személy töltse fel az akkumulátort anélkül, hogy ellenőrizné.","Ne töltse fel és ne használja, és értesítse a felelős szakembereket.","A sérült akkumulátorok elektromos és kémiai veszélyeket jelentenek, és szakmai értékelést igényelnek."],"g2-fahrerkabine":["Mi vonatkozik a meglazult tárgyakra a vezető területén?","A szerszámok a padlón vannak a vezérlőpedálok mellett.","Távolítsa el a tárgyakat, és tartsa szabadon a működési területet.","Vezetés közben csak az egyik lábával fogja meg a szerszámot.","Rejtsd el a meglazult részeket a vezetőülés alá.","A laza tárgyak elzárhatják a pedálokat, és ronthatják a jármű biztonságos működését."],"g2-uebergabe":["Műszakváltás után veszel át egy targoncát. Mit tartalmaz ez?","Egy kolléga használta utoljára a járművet.","Tegyük fel, hogy a kolléga átvette az összes ellenőrzést.","Végezze el a szükséges ellenőrzést és érdeklődjön az ismert hibákról.","Kezdje el az utazást anélkül, hogy a gépre nézne.","Az átvevő személynek használat előtt meg kell győződnie arról, hogy biztonságos állapotban van."],"g2-transportsicherung":["Egy magas tárgy meglazult a raklapon. Hogyan viselkedsz?","A rakomány fékezéskor előrebillenhet.","A villát különösen magasan vigye, hogy a teher stabil maradjon.","Csak lassan vegye az íveket, menjen egyenesen gyorsabban.","Állítsa fel stabilan a rakományt, és biztosítsa felborulás vagy leesés ellen.","A laza rakományokat szállítás előtt stabilizálni kell, hogy a fékezés és a menetmozgások ne okozzák leesésüket."],"g2-arbeitsende":["Mi a fontos egy felügyelet nélküli targoncánál?","Befejezed a műszakot, és elhagyod a területet.","Parkolja le biztonságosan a járművet, és biztosítsa elgurulás és illetéktelen használat ellen.","Hagyja bent a kulcsot, hogy a kollégák megtalálják a gépet.","Hagyja a villát szemmagasságban, hogy látható legyen.","A biztonságos parkolás magában foglalja a süllyesztett rakománykezelést, valamint a mozgás és az illetéktelen üzembe helyezés elleni védelmet."],"g2-bremsweg":["Miért kell különös figyelmet fordítani a terhelés alatti fékútra?","A targonca nehéz árukat szállít egy raktárfolyosón keresztül.","Mindig később fékezzen nagy teherrel, mint teher nélkül.","A sebességet a látási viszonyokhoz, a talajhoz és a terheléshez igazítsa.","Fékezéskor élesen emelje fel a rakományt, hogy jobban lassuljon.","A tömeg és az útviszonyok befolyásolják a féktávolságot; az adaptált sebesség kulcsfontosságú."],"g2-rampe":["Mit kell ellenőrizni, mielőtt felmászik egy meredek rámpán?","Az útvonal túl meredek lehet a jármű számára.","Haladjon a rámpán maximális sebességgel, függetlenül a lejtőtől.","Hajtson át a rámpa szélén felemelt rakomány mellett.","Ellenőrizze a megengedett meredekséget és a biztonságos üzemmódot a jármű műszaki adataiból.","Csak a tervezett működési határokon belüli rámpák használhatók; A kezelési utasítás és a terhelés ellenőrzése meghatározó."],"g2-zinke":["Egy raklap szélesebb, mint a villa távolsága. Mit kell figyelembe venni?","Szokatlanul nagy terhelést tervez vállalni.","Állítsa be a villa távolságát és a rögzítési pontokat a terhelésnek megfelelően.","Csak egy kapát használjon, ha a terhelés túl széles.","Emelje fel a terhet ferdén, amíg el nem éri a megfelelő pozíciót.","Az egyenletes és megfelelő teherfelvétel csökkenti a megcsúszást és a billenést."],"g2-betriebsanweisung":["Milyen szerepe van az operatív forgalomszabályozásnak?","A raktárban kijelölt egyirányú és gyalogos területek érvényesek.","Targoncára csak a közút szabályai érvényesek.","Kövesse a megadott útvonalakat és közlekedési szabályokat.","Hagyja figyelmen kívül a jelöléseket, ha a jármű be van rakva.","A vállalati útvonalak és a biztonsági szabályok védik a targoncaforgalmat és a gyalogosokat."],"g2-nothalt":["A kormány szokatlanul reagál vezetés közben. Mi a helyes?","A járművet már nem lehet a megszokott módon irányítani.","Vezessen nagyobb sebességgel, hogy a kormányzás érzékenyebb legyen.","Kompenzálja a hibát különösen nagy kormányelhajlásokkal.","Álljon meg biztonságos helyen, és ellenőrizze a járművet.","A meghibásodott kormányzás veszélyezteti a biztonságos vezetést; a gépet nem szabad továbbra is ellenőrizetlenül üzemeltetni."],"g2-anschlagkette":["Szabadon függő terhet szeretne targoncával mozgatni. Mi vonatkozik rá?","A villák alatt egy tehernek egy horgon kell lógnia.","Csak jóváhagyott eszközzel és megfelelő teherhordó berendezéssel.","Bármely lánc megteszi, ha nem nehéz a terhelés.","Rögzítse a láncot közvetlenül a két villa közé.","A szabadon lógó terhek megváltoztatják a stabilitást; A gyártó jóváhagyása és megfelelő létesítmények szükségesek."],"g2-rollenlast":["Egy hengeres alkatrész rögzítetlenül fekszik egy raklapon. mit csinálsz?","A rakomány szállítás közben elgurulhat.","Különösen szaggatottan közelítse meg a raklapot.","Biztosítsa az alkatrészt elgurulás ellen, mielőtt a raklapot felveszi.","Helyezze a fogakat elég magasra, hogy az alkatrész ne legyen látható.","A kerek vagy gördülő terhek megbízható védelmet igényelnek a helyzetváltozásokkal szemben."],"g2-pruefplakette":["Honnan tudja, hogy a targonca használható-e?","Ellenőrző matrica van a gépre ragasztva.","Bármely matrica mindig helyettesíti a napi szemrevételezést.","A hézag hiánya pótolható óvatos vezetéssel.","A jármű ellenőrzése mellett figyelembe kell venni az érvényes vizsgálati állapotot és az üzemeltetési engedélyt is.","Az ismétlődő tesztelések és a napi működési ellenőrzések különböző biztonsági funkciókat látnak el."],"g2-licht":["A raktárban hirtelen kialudt a világítás. Mi a helyes?","Már nem láthatod biztonságban az akadályokat az úton.","Hagyja abba a vezetést, amíg a biztonságos láthatóság nem garantált.","Növelje a vezetési sebességet a sötét terület elhagyásához.","Felemelt villákkal haladjon tovább szemrevételezés nélkül.","Hatékony biztonsági intézkedések nélkül nem szabad olyan útvonalon haladni, amelyet nem lehet biztonságosan figyelmen kívül hagyni."],"g2-ueberhang":["A teher messze túlnyúlik a villa oldalán. Mit ellenőriz?","Szűk kapun szeretné átszállítani a raklapot.","Kompenzálja az oldalsó vetületet egy gyors görbével.","Vezetés előtt mérje fel a távolságot, a stabilitást és a megengedett teherbírást.","Vezesse a rakományt maximális sebességgel, annak alakjától függetlenül.","A túlnyúlások növelik az ütközések kockázatát, és megváltoztathatják a stabilitást és a szükséges forgalmi teret."],"g2-wartungsbereich":["A karbantartási terület előtt sorompók vannak. hogy viselkedsz?","A szokásos útvonal átmenetileg le van zárva.","Mozgassa röviden az akadályokat, és észrevétlenül haladjon át rajta.","Vezessen át közvetlenül a munkaterületen terhelés alatt.","Figyelje meg a lezárást, és válasszon egy jóváhagyott alternatív útvonalat.","A körbekerített területekre engedély nélkül behajtani és áthajtani tilos."],"g2-bremsprobe":["Mikor van értelme az üzemi fék működési vizsgálatának?","Munka előtt előkészíti a targoncát.","A használat előtti kötelező ellenőrzés részeként.","Csak súlyos baleset után végezze el.","Csak akkor, ha a targonca már elérte a nagy sebességet.","Használat előtt ellenőrizni kell a biztonság szempontjából fontos létesítmények működőképességét."],"g2-fahrzeuganhaenger":["Utánfutót akar húzni egy targoncával. Mi szükséges?","A cég fuvarozást tervez mellékelt rakomány mellett.","Rögzítse az egyes pótkocsikat egy villához ellenőrzés nélkül.","Vegye figyelembe a gyártó jóváhagyását, a megfelelő tengelykapcsolót és a megengedett húzóterhelést.","Csak növelje a guminyomást és induljon el.","A vonatközlekedés biztonságosan csak a műszaki előírásoknak megfelelően és megfelelő összeköttetéssel lehetséges."],"g2-rueckfahrt":["Mi a fontos a targoncával való tolatásnál?","Zavaros terület van a raktárfolyosón.","Mindig csak a visszapillantó tükörbe nézzen, függetlenül a környezettől.","Vezessen láthatóság nélkül, amíg a kürtöt egyszer megnyomta.","Biztonságosan figyelje meg az útvonalat és az emberek területét, és ha szükséges, tájékoztassa őket.","A tolatáshoz tiszta rálátás vagy hatékony kiegészítő biztonsági intézkedések szükségesek."],"g2-lastentnahme":["Kivesz egy raklapot a magas polcról. Mi a helyes?","Előfordulhat, hogy a paletta nincs középre állítva.","Biztonságosan vegye fel a terhet, és leengedés előtt stabilizálja.","Hagyja, hogy a raklap oldalra lendüljön, miközben kihúzza.","Ellenőrizze a megemelt raklap alatt, hogy nem sérült-e.","A szabályozott emelés és süllyesztés megakadályozza a rakományok leesését és a veszélyes mozgásokat."],"h2-absenkweg":["Miért kell a munkaállvány alatti területnek szabadnak maradnia?","A kosár le van engedve, és az anyagokat helyezik alá.","Nyomja le az anyagokat a kosárral.","Csak a kezelő lábát tartsa szemmel.","Leengedéskor kerülje a zúzódás és ütközés veszélyét.","A süllyesztési terület nem tartalmazhat embereket vagy akadályokat, amelyek beszorulhatnak."],"h2-transporthoehe":["Hogyan lehet mozgatni egy mobil színpadot egy alacsony átjárón?","A hézag alacsonyabb, mint a kiterjesztett gém.","Helyezze az emelőkosárt megfelelő szállítási helyzetbe a kezelési útmutató szerint.","Hagyja kinyújtva a gémet, és haladjon tovább a mennyezet alatt.","Nyomja a kosarat az ajtókeret oldalához.","Mozgás esetén a teljes magasságnak és szállítási helyzetnek meg kell egyeznie a gyártó specifikációival és az átjáróval."],"h2-bodenoeffnung":["A színpad melletti emeleten van egy nem biztosított nyílás. Hogyan reagálsz?","A nyílás közelében egy vezetési vagy támogatási pont található.","Helyezzen egy támaszt közvetlenül a nyílás szélére.","Változtassa meg a telepítési helyet, vagy ellenőriztesse szakszerűen a teherbírást és a rögzítést.","Csak kartondobozsal fedje le a veszélyes helyet.","A nyílások és az élek meghibásodhatnak támasztó terhelés hatására, és ezeket hatékonyan figyelembe kell venni."],"h2-rettungsperson":["Miért kell egy másik személynek ismernie a mentési eljárást?","A kezelő a tetején cselekvőképtelenné válhat.","Így a kosárban végzett munka általában biztonság nélkül történhet.","Hogy a színpadot a megengedettnél gyorsabban lehessen üzemeltetni.","Hogy vészhelyzetben biztonságos mentést lehessen kezdeményezni.","A mentési koncepciónak figyelembe kell vennie a földi segítségnyújtást hiba vagy vészhelyzet esetén."],"h2-werkzeugabwurf":["Mi vonatkozik a nagy magasságban lévő szerszámokra?","Egy laza szerszám áteshet a kosár szélén.","Rögzítse a szerszámokat úgy, hogy senkit ne veszélyeztessen vagy leessen.","Egyszerűen helyezze a szerszámokat a korlátra a terhelés csökkentése érdekében.","Ha szükséges, dobja le a szerszámokat a kosárból.","A leeső tárgyak veszélyeztetik az alatta lévőket; Az anyagot biztonságosan kell tárolni."],"h2-trittstufe":["Egy doboznak további állóhelyként kell szolgálnia a kosárban. Mi a helyes?","Ellenkező esetben alig éri el a munkahelyét.","Helyezze a dobozt a korlátra, és mássz fel rá.","Ne mássz fel rögtönzött magaslatokra; Használjon megfelelő munkaeszközt.","Szándékosan töltse be a kosarat a megengedett magasságon túl.","A rögtönzött emelések rontják a tervezett leesés elleni védelmet, és nem megengedettek."],"h2-lastverteilen":["Mire kell figyelni, ha többen vannak a munkakosárban?","Két ember dolgozik a kosárban nehéz szerszámokkal.","A terhelést kizárólag a szerszám mérete alapján ítélje meg.","A nehéz szerszámokat közvetlenül a védőkorláton tárolja.","Ne lépje túl a megengedett kosárterhelést, beleértve az embereket és a szerszámokat.","A megengedett teherbírás magában foglalja a kosárban lévő összes embert, anyagot és szerszámot."],"h2-abstuetzplatte":["Mikor veszik figyelembe a kiegészítő alátéteket a támasztékokhoz?","A beépítési padló csak korlátozott terhelést képes elviselni.","Ha ez szükséges a biztonságos terheléselosztáshoz az előírásoknak megfelelően.","Annak érdekében, hogy a támasztékokat a lehető legközelebb helyezzék el az építési gödör széléhez.","Hosszabb tartomány használatához gyártói információk nélkül.","A biztonságos támasztóerők biztosításához elegendő érintkezési felületre van szükség."],"h2-baugrube":["A színpadot közvetlenül az építési gödör szélén kell elhelyezni. Mit ellenőriz?","Az altalaj oldalirányban engedhetett az ásatási gödör miatt.","Nyújtsa ki a támasztékokat az ásógödörbe.","Biztosítson elegendő biztonsági távolságot és teherbíró képességet a felszín alatt.","Csak a kosár lassú emelésével kompenzálja a kockázatot.","Az ásatási gödrök befolyásolhatják a stabilitást a lejtő és az altalaj meghibásodása miatt."],"h2-witterung":["A jegesedés használat közben megtörténik. Hogyan viselkedsz?","A vezérlőfelületek és a munkaterület simává válnak.","Emelje fel a színpadot a hó és a jég elkerülése érdekében.","Hagyja figyelmen kívül a figyelmeztetéseket, amíg az emelőkosár világít.","Szakítsa meg a munkát és értékelje újra az üzemi feltételeket a kezelési útmutató szerint.","Az időjárás változásai megváltoztathatják a felelősséget, a működőképességet és a biztonságos használat határait."],"h2-aufbaukontakt":["Az acélszerkezet korlátozza a kosár útját. Mi a fontos?","Emeléskor fennáll a becsípődés veszélye a kosár és a tartó között.","Tervezze meg a mozgásokat úgy, hogy teste és kosara ne szoruljon be.","Gyorsítsa meg az utazást, hogy a kosár gyorsabban elhaladjon mellette.","Tolja oldalra a szerkezetet a kosárral.","A platform és a környezet közötti csípési pontok gondos megfigyelést és irányított mozgást igényelnek."],"h2-sicherheitsabstand":["Mikor kell lezárni egy színpad veszélyes területét?","A telek alatt tömegközlekedési útvonal halad el.","Csak akkor, ha egy tárgy már leesett.","Ha harmadik személyeket mozgás vagy leeső tárgyak veszélyeztethetnek.","Soha, mivel a munkakosár alapvetően minden veszélyt megelőz.","A színpad alatti és melletti területet védeni kell az előrelátható veszélyek ellen."],"h2-korbtor":["Mi vonatkozik a munkakosár bejárati ajtajára?","Már munkamagasságban vagy.","Hagyja nyitva az ajtót, hogy gyorsabban tudjon kiszállni.","Kösse meg az ajtót tartósan nyitva egy kötéllel.","Tartsa zárva az ajtót a mellékelt zárszerkezetnek megfelelően.","A mellékelt zárak a munkaketrecből való kiesés elleni védőintézkedések részét képezik."],"h2-energieleitung":["Mi történik, ha a felsővezeték nincs biztonságosan kikapcsolva?","Ön a közelükben lévő emelőkosárral dolgozik.","Ügyeljen az előírt biztonsági távolságokra és a szükséges védőintézkedésekre.","Mozgassa a kosarat közvetlenül a vonal elé, amíg nem érinti.","Bízzon a műanyag abroncsokban és dolgozzon hézagok nélkül.","Az elektromos villanások közvetlen érintkezés nélkül is lehetségesek; Biztonsági távolságok szükségesek."],"h2-schwanken":["A munkakosár szokatlanul erősen lendülni kezd. Mi a helyes?","A mozgást már nem irányítják.","Szabályozhatatlanul állítsa be a gyors ellenmozdulatokkal.","Állítsa le a mozgást és ellenőrizze az okot vagy a működési feltételeket.","Tegyen további embereket a kosárba, hogy nehezebb legyen.","A szokatlan rezgés nem megfelelő működési feltételeket vagy hibás működést jelezhet."],"h2-ladegeraet":["Az elektromosan működtetett fokozat töltőkábele megsérült. mit csinálsz?","Csatlakoztatáskor látható a sérült szigetelés.","Nedves kesztyűvel érintse meg a sérülést.","A dugót a lehető legerősebben nyomja be az aljzatba.","Ne indítsa el a töltési folyamatot, és ellenőriztesse szakemberrel a kábelt.","A sérült elektromos vezetékek áramütés és tűzveszélyt jelentenek."],"h2-gelaenderanbau":["El tudod távolítani magad a korlátot, hogy közelebb kerülj?","Egy alkatrész megakadályozza, hogy emberek közeledjenek a munkaterülethez.","Ne módosítsa vagy távolítsa el a védőeszközöket egyedül.","Emelés után csavarja le a korlátot és szerelje fel később.","Folytassa a munkát korlát nélkül, amíg valaki áll mellette.","A szerkezeti védőeszközöket a megengedett előírások és biztonságos csereintézkedések nélkül nem szabad megváltoztatni."],"h2-lastkran":["Használható a platform daruként teher emelésére?","Az anyagot a munkakosár mellett szabadon lógva kell szállítani.","Amikor a súly kisebb, mint a saját testsúlya.","Csak akkor, ha a gyártó és a berendezés kifejezetten engedélyezi ezt a különleges felhasználást.","Egyszerűen rögzítsen egy kampót a korlátra, és emelje fel az anyagot.","A munkaállványok nem automatikusan daruval vagy további függesztett rakományokhoz vannak tervezve."],"h2-arbeitsvorbereitung":["Mit jelent az új helyszín előkészítése?","Még nem ismeri az építkezést.","Csak becsülje meg a távolságot a legközelebbi parkolótól.","A környezettől függetlenül azonnal húzza ki teljesen.","Felméri a veszélyeket, a talajt, a közlekedési útvonalakat, a mentési és felszerelési alkalmasságot.","A helyhez kötött kockázatértékelés a biztonságos működési feltételek előfeltétele."],"h2-kabelschlaufe":["A színpad útjában egy tápkábel húzódik. Mi a helyes?","A kábel beszorulhat a mozgás során.","Tisztítsa meg az utat, és óvja az elektromos kábeleket a sérülésektől.","Használja a kerekekkel ellátott kábelt útküszöbként.","Emelje fel a kosarat a padlófelület ellenőrzése nélkül.","Az elgázolt vagy összenyomódott kábelek elektromos és mechanikai veszélyeket okozhatnak."],"h2-leitungsnaehe":["Ki tisztázza az elektromos rendszer védelmi intézkedéseit?","A platformnak a feszültség alatt álló berendezések közelében kell működnie.","A kosárban lévő személy kizárólag szeme alapján dönt.","A felelős hatóságok bevonása és összehangolt védelmi intézkedések végrehajtása.","A távolság meghatározása csak a munka megkezdése után történik.","Az elektromos rendszerek közelében végzett munka tervezett és összehangolt védelmi intézkedéseket igényel."],"h2-funkkommunikation":["Miért kell egyértelműnek lennie a padló és a kosár közötti jelzéseknek?","A földön tartózkodó személy segíti a manőverezést.","Hogy egyszerre többen egymásnak ellentmondó utasításokat adhassanak.","Hogy a vészsüllyesztés utasítás nélkül is kipróbálható legyen.","Így a mozgásokat csak egyértelmű kommunikáció után hajtják végre.","A tiszta kommunikáció csökkenti a helytelen mozgásokat és az ütközéseket manőverezés közben."],"h2-neuebedienung":["Más típusú színpadra vált. Mi szükséges?","A működési funkciók jelentősen eltérnek egymástól.","Készülékspecifikus utasítás önálló használat előtt.","Csak olvassa el a cég logóját a készüléken.","Próbaút a már kihúzott kosárral, instrukciók nélkül.","A minősítés önmagában nem helyettesíti az adott eszköztípuson belüli oktatást."],"h2-steckanschluss":["Mit kell ellenőrizni a töltő csatlakoztatása előtt?","Az elektromos munkaállványt fel kell tölteni.","Használjon bármilyen aljzatot állapotától és biztosítékától függetlenül.","Ellenőrizze a megfelelő csatlakozást és a sértetlen kábelt a gyártó utasításai szerint.","Töltés közben rendszeresen húzza ki a hálózati csatlakozót.","A megfelelő és sértetlen elektromos csatlakozások védelmet nyújtanak az áramütés és a tűz ellen."],"h2-absperrpersonal":["Emelési munka közben személy lép be a körbekerített területre. mit csinálsz?","Közvetlenül a munkakosár alatt láthat egy személyt.","Ha a személy védősisakot visel, folytassa a vezetést.","Figyelmeztető jelként dobjon le egy szerszámot az irányukba.","Állítsa le a veszélyes mozgást, és tisztítsa meg a területet.","A sorompó nem helyettesíti a veszélyes terület megfigyelését működés közben."],"k2-arbeitsplanung":["Mit kell beépíteni a daruzás előtti munka előkészítésébe?","A terhelés, a helyszín és a szállítási útvonal még nem egyeztetett.","Először a legnehezebb terhet emelje fel további tervezés nélkül.","Csak a legrövidebb útvonalat jelölje meg a csarnok padlóján.","Előzetesen tisztázza a teherbírást, a hevedereket, a rakomány útját és a veszélyes területet.","A tervezett darumozgás megfelelő teherkezelést, biztonságos útvonalakat és összehangolt védőintézkedéseket igényel."],"k2-hakenposition":["Hogyan kell a daru kampóját a rakomány fölé helyezni emelés előtt?","A rögzítési pontok a daru alatt vannak.","Lehetőleg függőlegesen a súlypont felett az ütközésnek megfelelően.","Messze oldalra tolva, hogy a rakomány gyorsabban belendüljön.","Mindenképpen a rakomány külső szélén, a súlyponttól függetlenül.","Az erő függőleges alkalmazása és a megfelelő rögzítési pontok csökkentik az oldalirányú mozgást és az ellenőrizetlen mozgásokat."],"k2-hakengabel":["Egy teherhorog észrevehető deformációt mutat. Mi vonatkozik rá?","Úgy tűnik, hogy a horog a szokásos állapotából felhajlott.","Hajlítsa vissza a deformációt a következő terhelésnél.","Állítsa le a daru működését, és ellenőriztesse szakemberrel a horgot.","Csak könnyű terheket szereljen fel, és folytassa a munkát.","A deformáció befolyásolhatja a horog biztonságát; jogosulatlan további felhasználása nem megengedett."],"k2-zugueberlast":["A teher az eredetileg feltételezettnél nehezebb. mit csinálsz?","A felkészülés során új súlyinformációk merülnek fel.","Cserélje ki a biztonsági tartalékot gyorsabb emeléssel.","Hagyja figyelmen kívül a rakomány súlyát, ha egy másik ponthoz rögzíti.","Határozza meg a tényleges terhelést, és ellenőrizze újra a terhelési határokat.","A biztonságos emeléshez megbízható terhelési adatokra és minden vonatkozó teherbírás betartására van szükség."],"k2-arbeitskorb":["Egy közönséges daruhorog könnyen szállíthatja az embereket?","Az ember magas munkahelyre szeretne eljutni.","Nem, a személyszállítás engedélyezett speciális létesítményeket és intézkedéseket igényel.","Igen, ha az ember a hevederkötélbe kapaszkodik.","Igen, amint az agyvérzést különösen lassan hajtják végre.","Személyek szállítása csak az erre a célra biztosított különleges feltételek mellett engedélyezett."],"k2-bruecke":["Egy híddaru mozog a közös csarnok útján. Mi a fontos?","Az alkalmazottak a szállítási útvonal alatt maradnak.","Vezessen úgy, hogy a rakomány közvetlenül az alkalmazottak feje felett van.","Hatékonyan tartsa tisztán és biztonságosan a rakomány útvonalát és a közlekedési területet.","Csak a figyelmeztető kürtöt használja további intézkedések helyett.","A veszélyeztetett személyek nem tartózkodhatnak függő teher alatt vagy a szállítási útvonalukban."],"k2-zweitekrane":["Két daru dolgozik átfedő területen. Mi szükséges?","Gémek vagy rakományok ütközhetnek egymással.","Mindkét darukezelő egy időben dolgozik előzetes egyeztetés nélkül.","A mozgásokat szándékosan felgyorsítják, hogy elkerüljék a kereszteződéseket.","Koordinálja a műveleteket és tegye meg a megfelelő intézkedéseket a kölcsönös fenyegetések megelőzésére.","Az átfedő munkaterületek összehangolt működésszervezést és megfelelő biztosítékokat igényelnek."],"k2-pruefbuch":["Mi a jelentősége a kötelező ismétlődő daruvizsgálatnak?","A gépet rendszeresen használják az üzemeltetés során.","Az üzemi ellenőrzést kiegészíti az előírt szakértői vizsgálattal.","Véglegesen helyettesít minden szemrevételezést a munka megkezdése előtt.","Csak ütközés után szükséges.","Az ismétlődő ellenőrzéseknek és a folyamatos működési ellenőrzéseknek különböző feladatai vannak."],"k2-absetzflaeche":["A tervezett elhelyezési terület egyenetlen. Hogyan viselkedsz?","A rakomány felborulhat, amikor felhelyezik.","Helyezze a terhet az egyik sarkára, és hagyja változatlanul lógni.","Készítsen megfelelő, teherbíró és stabil alapot vagy felületet.","Süllyesztés közben helyezzen egy személyt a teher alá.","Az elhelyezési területeknek biztonságosan meg kell tartaniuk a rakományt, és meg kell akadályozniuk a veszélyes billenést vagy elgurulást."],"k2-anfahrbereich":["Mielőtt a daru elindulna, egy személy tartózkodik az utazási területen. mit csinálsz?","Az útvonalat egy személy blokkolta.","Tolja félre a személyt egy rövid próbaúttal.","Szemrevételezés nélkül induljon el a végálláskapcsolóval.","Csak akkor kezdje meg a mozgást, ha a veszélyes terület szabad és biztonságos.","A vezetés és a forgó mozgások nem veszélyeztethetik az embereket."],"k2-schlaffseil":["Miért nem lazulhat meg ellenőrizhetetlenül az emelőkötél lerakáskor?","A teher rajta van, a horog tovább süllyesztve.","Hogy a kötél és a horgok ne szoruljanak be, és ne legyenek kitéve ellenőrizetlen terhelésnek.","Hogy a teher ezután oldalirányban húzható legyen a kötéllel.","Így a hevederek leválnak a horogról.","Az ellenőrizetlen kábelvezetés összegabalyodáshoz és veszélyes rakománymozgáshoz vezethet."],"k2-pendel":["A szállított rakomány lötyögni kezd. Mi a helyes?","A rakomány oldalirányban a tervezettnél jobban elmozdul.","Kompenzáljon gyors ellenmozgással és teljes sebességgel.","Csökkentse a mozgásokat ellenőrzött módon és nyugodt ingázást anélkül, hogy emberek tartózkodnának a veszélyes területen.","Tartsa a lengő terhet puszta kézzel.","Az oszcilláló terhelések hatással lehetnek az emberekre és a létesítményekre; a nyugodt mozgások csökkentik a kockázatot."],"k2-funkakku":["A daru rádióvezérlésének akkumulátora gyenge. Mi vonatkozik rá?","A csatlakozás megszakadhat emelés közben.","Gyorsan emelje fel a terhet, mielőtt a vezérlés meghibásodik.","Ha a kapcsolat megszakad, mozgassa a terhet a heveder meghúzásával.","Használat előtt gondoskodjon megbízható vezérlőcsatlakozásról.","A megbízható vezérlés és kommunikáció a szabályozott darumozgások előfeltétele."],"k2-mehrereanschlaeger":["Két ember egyszerre ad különböző jeleket a darukezelőnek. Mi a helyes?","A jelek ellentmondanak egymásnak.","Szakítsa meg a mozgást és tisztázza a felelősséget.","Inkább a távolabbi személy jelét.","Folytassa a mozgást saját érzései szerint.","A daruvezetőknek világos és egyértelmű kommunikációra van szükségük, különösen akkor, ha a rakodási útvonalak zavarosak."],"k2-endabschaltung":["Miért nem szabad a végálláskapcsolót visszaélni normál löketkorlátozásként?","A terhet gyakran a maximális emelési távolságig mozgatják.","A végálláskapcsolók általában gyorsabb emelést tesznek lehetővé láthatóság nélkül.","A végálláskapcsolók biztonsági eszközök, és nem helyettesítik a szabályozott működést.","Minden ütésnél a lehető legerősebben kell megütni őket.","A biztonsági berendezések a veszélyek elleni védelemre szolgálnak, és nem szabad a tervezett módon túlhasználni."],"k2-wetterbeobachtung":["A szél nagy területi terhelés mellett jelentősen megnövekszik. Mi szükséges?","Egy nagy részterület vitorlaként működik.","Mindig emelje magasabbra a terhet, hogy a szél kevésbé legyen hatással.","Cserélje ki a hevedereket vékonyabbakra.","Mérje fel a szél- és működési határokat, és szükség esetén állítsa be az emelést.","A szél jelentős többleterőt és ingamozgást generálhat, különösen nagy területű terhelések esetén."],"k2-ortswechsel":["Mi a fontos az autódaru új helyre költöztetésekor?","Változnak az altalaj és az alátámasztási viszonyok.","Mielőtt ismét felveszi a rakományt, ellenőrizze az állvány helyét és támasztékát.","Alkalmazza az előző hely beállításait ellenőrzés nélkül.","Állítsa be a támasztékot emelés közben.","Az egyes telepítési helyeken eltérő talaj- és támasztóterhelési feltételek vonatkozhatnak."],"k2-betriebsbereich":["Egy darunak az utca túloldalán kell működnie. Mit kell tisztázni?","Harmadik felek bejuthatnak a veszélyes területre.","Csak figyelmeztető kürttel biztosítsa az utat.","Szükséges lezárások, szavazás és védelmi intézkedések a hub előtt.","Emelje fel a rakományt a járművek fölé, amilyen gyorsan csak lehetséges, anélkül, hogy rögzítené.","A biztonságos forgalomirányítás megakadályozza a harmadik felek számára a rakományokból és a daruk mozgásából eredő indokolatlan kockázatot."],"k2-hochheben":["A próbaemelés után egy rakomány egyértelműen ferdén lóg. Mi a helyes?","A fókuszt láthatóan rosszul ítélték meg.","Folytassa az emelést, hogy az egyensúlyhiány magától helyreálljon.","Egy személy húzza meg a támasztó terhet.","Helyezze le biztonságosan a rakományt, és ellenőrizze újra a rögzítést és a súlypontot.","A próbaemelő a helytelen rögzítés és az instabil rakományhelyzet észlelésére szolgál a szállítás előtt."],"k2-schwebelast":["Felemelt terhet hagyhat felügyelet nélkül lógva?","A műszak véget ér, de a teher még mindig a horgon.","Nem, biztonságosan engedje le a rakományt és rögzítse megfelelően a darut.","Igen, ha a daru elmozdulás ellen reteszelve van.","Igen, amíg van egy figyelmeztető tábla a földön.","Elvileg a felfüggesztett terheket nem szabad felügyelet nélkül hagyni."],"k2-mitnahme":["Egy kolléga darus rakományon szeretne lovagolni. Mi vonatkozik rá?","A rakományt magasabb pontra kell szállítani.","A lovaglás megengedett, ha a kolléga sisakot visel.","Embereket nem szabad normál rakományon szállítani, vagy rákapcsolni.","Az utazás mindig megengedett, amíg a kolléga a daruvezető előtt ismert.","Emberek szállítása teherekkel együtt jelentős leesési és összezúzási kockázatot jelent."],"k2-warnsignal":["A daru működési figyelmeztető rendszere meghibásodik. Mi a helyes?","Indulás előtt már nem lehet figyelmeztetni.","Hagyja figyelmen kívül a rendszert, amikor a motor jár.","Cserélje ki véglegesen a figyelmeztetést a ház megérintésével.","Jelentse a biztonsággal kapcsolatos hibát, és szakítsa meg a műveleteket az utasításoknak megfelelően.","A szükséges figyelmeztető eszközöknek működőképesnek kell lenniük, hogy az emberek időben megvédhetők legyenek."],"k2-schneekante":["Az autódarut fagyos, egyenetlen talajon kell alátámasztani. Mi vonatkozik rá?","A talaj felolvadásakor elveszítheti teherbíró képességét.","Mérje fel a terhelhetőséget és a támogatási helyzetet a tényleges körülmények között.","A fagyott talajnak mindig van teherbíró képessége.","Csak kis kövekre helyezzen támasztékokat.","A hőmérséklet, a páratartalom és az altalaj szerkezete befolyásolja a daruhelyek teherbíró képességét."],"k2-laufkatze":["Egy kocsi egy akadály felé halad. Hogyan viselkedsz?","Van egy tárgy a vezetési területen.","Lassan tolja el a tárgyat a teherrel együtt.","Időben hagyja abba a mozgást, és távolítsa el biztonságosan az akadályt.","Haladjon el az akadály mellett megnövelt sebességgel.","A daru mozgását úgy kell irányítani, hogy ne ütközzenek akadályba."],"k2-anschlagaufnahme":["A rakományt egy nem kijelölt fűzőlyukkal kell felvenni. Mi a helyes?","A fűzőlyuk csak burkolat felszerelésére szolgálhatott.","Mindegyik fűzőlyuk teljes daruterhelésre alkalmas.","Csak egyszerre két emberrel töltse be a fűzőlyukba.","Használat előtt ellenőrizze a rögzítési pont terhelhetőségét és alkalmasságát.","Nem minden meglévő fűzőlyuk stabil rögzítési pont a daru terheihez."],"l2-seilbruch":["Egy drótkötélen több elszakadt vezeték látható. Mi a helyes?","A töréspontok a teherhordó kötél területén vannak.","Ne használja tovább az emelőszerkezetet, és végeztesse el azt szakszerű vizsgálattal.","Hajtsa vissza a huzalvégeket puszta kézzel.","Ha a terhelés különösen könnyű, folytassa a kötél használatát.","A huzalszakadás eldobási kritérium lehet; A sérült köteleket szakszerűen kell felmérni."],"l2-schaekel":["Mi a döntő a bilincs használatakor?","Egy bilincs köti össze a hevedert és a rakományt.","Cserélje ki a csavart bármilyen szöggel.","Ellenőrizze a megfelelő teherbírást, sértetlen állapotot és a megfelelő csavarokat.","A szín alapján becsülje meg a terhelhetőséget.","A bilincseket megfelelő méretűnek kell lenni, azokat teljesen és a terhelés tervezett irányában kell használni."],"l2-tragfaehigkeit":["Mit kell figyelembe venni több szál használatakor?","A szálak a függőlegeshez képest szögben futnak.","Egyszerűen adja össze az egyes szálak teherbírását tetszés szerint.","Csak a legkönnyebb szálra akassza fel a terhet.","Vegye figyelembe a horgony és szög teljes típusának teherbíró képességét.","A dőlésszög és az effektív szálak száma jelentősen befolyásolja a megengedett terhelést."],"l2-schweissnaht":["Rögzített rögzítési pontot lehet hegeszteni egy terhelésre?","A rakomány számára nincsenek megfelelő kijelölt felvételi pontok.","Csak megfelelően tervezett és jóváhagyott rögzítési pontokat használjon.","Tesztelés nélkül minden hegesztési varrat elegendő.","Helyezzen be egy kampót a fémlemez nyílásán.","A rögzítési pontoknak bizonyítani kell, hogy alkalmasak az emelés során fellépő erőhatásokra."],"l2-einseitig":["A teher az egyik oldalon lényegesen nehezebb. Hogyan állsz hozzá?","A súlypont a geometriai középponton kívül van.","Hagyja az összes szálat egyforma hosszúságúra, függetlenül a súlyponttól.","Határozza meg a súlypontot, és ennek megfelelően állítsa be a pozíciót.","Először emelje fel a terhet teljes emelési magasságba.","Ha a súlypont nem a középpontban van, a terhelés váratlanul megbillenhet, vagy az egyes szálak túlterhelődnek."],"l2-kettenriss":["Mi vonatkozik a látható repedésekkel rendelkező lánchevederekre?","Repedés van az egyik láncszemen.","Jelölje meg a repedést festékkel, és változatlanul emelje fel.","Tekerje be a linket dróttal, és használja újra.","Azonnal távolítsa el a láncot, és értesítse a felelős személyt.","A teherhordó láncszemek repedései biztonsági szempontból jelentős károk, és leszerelést igényelnek."],"l2-lastfuehrung":["Hogyan szállíthat nagy terhet, ha fennáll az elfordulás veszélye?","Emelés közben a teher oldalra billenhet.","Használjon megfelelő vezetőeszközöket és biztonságos távolságot.","Vezetés közben tartsa a terhet közvetlenül a kezei között.","Lépjen a teher alá, és igazítsa alulról.","A rakományvezetés nem okozhat kezet vagy testet a veszélyzónába."],"l2-schnueren":["Mi a fontos a fűzők rögzítésekor?","A heveder egy alkatrész körül van megvezetve.","Ugyanolyan teherbírást feltételez, mint bármely más típusú horgony.","Vegye figyelembe a rögzítés típusának megfelelőségét és a megengedett terhelést a jelölés szerint.","Ellenőrzés nélkül húzza össze a heveder fogaskerekét bármilyen mértékben.","A csipke rögzítésének típusa megváltoztathatja a megengedett teherbírást, és helyesen kell használni."],"l2-winkelmesser":["Miért nem hagyhatja figyelmen kívül a lapos szálszöget?","Két hevedervonal közel vízszintesen halad a rakományig.","A lapos szög automatikusan erősebbé teszi a szálat.","A terhelés a szögtől függetlenül mindig egyenlően oszlik el.","A nagy szálerők meghaladhatják a megengedett teherbírást.","A függőlegeshez képesti szög növekedésével a szálakra ható feszültségek nőnek."],"l2-heisse-last":["Mit kell ellenőrizni forró terhelés esetén?","Egy acél alkatrészt nemrég hőkezeltek.","Vegye figyelembe a hevederek hőmérsékleti határait és a megfelelő kiválasztását.","Minden textil heveder bármilyen hőmérsékletnek ellenáll.","A címkézés nem számít, ha meleg.","A hőmérséklet befolyásolhatja a hevederek megengedett teherbírását."],"l2-abstand":["Be tudja tenni az ujjait a teher alá, amikor lerakja?","A terhelésnek milliméteres pontossággal kell egy felületre szállnia.","Igen, ha munkakesztyűt visel.","Nem, tartsa a távolságot és használjon megfelelő segédeszközöket.","Igen, ha a daru mozgása különösen lassú.","A teher és az alap közötti testrészek beszorulhatnak."],"l2-verbindung":["A hevederlánc egyik összekötő láncszeme nincs reteszelve. Mi vonatkozik rá?","A rögzítő hiányzik.","Használja a reteszt a zár nélkül, amikor senki sem figyel.","Ragassza le az elemet ragasztószalaggal.","Ne üssön addig, amíg a rögzítő nincs megfelelően rögzítve.","Az összekötő elemeket teljesen és a kialakításuknak megfelelően kell rögzíteni."],"l2-lasthaken":["Mit kell ellenőrizni, amikor daruhorgon lóg?","Több hevedert kell a horogba vezetni.","Biztosítsa a horgok és a felfüggesztés biztonságos illeszkedését és megfelelőségét.","Helyezzen hevedereket a horog hegyére.","Cserélje ki a horogzárat kábelkötegelőre.","Az erőt rendeltetésszerűen kell alkalmazni a kijelölt területeken."],"l2-fasern":["Az emelőheveder súlyos érdülést és rostkárosodást mutat. Mi a helyes?","A tartószálak láthatóan sérültek.","Fedje le a sérülést egy másik csomóval.","Válassza le az emelőpántot, és vizsgáltassa meg szakemberrel.","Ezután gyorsabban emelje fel a terhet.","A sérült teherbíró szálak jelentősen csökkenthetik az emelőheveder teherbíró képességét."],"l2-anheben":["Mi történik közvetlenül az emelés első centimétere után?","A teher éppen felemelkedik az alapjáról.","Vezérlés nélkül húzza a terhet teljes magasságába.","Ellenőrizze a terhelés alatt, hogy a hevederek meg vannak-e feszítve.","Ellenőrizze az ütköző helyzetét, az egyensúlyt és a mozgási viselkedést.","Az ellenőrzött próbaemelés láthatóvá teszi a lehetséges instabilitásokat a további szállítás előtt."],"l2-lastgewichte":["A rakomány súlya ismeretlen. Mi a helyes?","Az alkatrészen nincs súlyjelzés.","A hevederek kiválasztása előtt határozza meg a terhelhető súlyt.","Becsülje meg a súlyt a rakomány színe alapján.","Használjon bármilyen dupla hosszúságú hevedert.","Ismert vagy megbízhatóan meghatározott tömeg nélkül a hevederek alkalmassága nem ellenőrizhető biztosan."],"l2-lose-teile":["Az emelendő rakományon laza szerszámok vannak. mit csinálsz?","A szerszámok leeshetnek emelés közben.","Tartsa a szerszámokat egy kézzel vezetés közben.","Felemelés előtt távolítsa el vagy hatékonyan rögzítse a laza tárgyakat.","Kicsit gyorsabban emelje meg a terhet, hogy ne csússzon el semmi.","A laza tárgyak leeshetnek, és veszélyeztethetik a területen tartózkodó embereket."],"l2-wind":["Erős szélben nagy rakományt rögzítenek. Mi vonatkozik rá?","Az alkatrész nagy felületet biztosít a szélnek a támadáshoz.","Emelje fel a terhet anélkül, hogy figyelembe venné a lengő mozgásokat.","További személyeknek közvetlenül kell tartaniuk a terhet.","Mérje fel a szélviszonyokat, és tartózkodjon az emeléstől, ha a helyzet nem biztonságos.","A szélerő befolyásolhatja a rakomány vezetését és stabilitását szállítás közben."],"l2-unterlage":["Miért fontosak a megfelelő dokumentumok az elválasztás során?","Egy kerek teher legördülne a földön.","Helyezze le határozottan a terhet, és szükség esetén biztosítsa elgurulás ellen.","Hagyja a terhet közvetlenül a hevedereken állni.","A dokumentumokat csak lerakás után tolja a töltet alá.","A megfelelő támasztékok megakadályozzák a felborulást és a nem kívánt mozgásokat lerakáskor."],"l2-transportweg":["Mit kell egyeztetni a rakomány elszállítása előtt?","A rakományt több munkaterületen mozgatják.","Csak a hub várható időtartama.","Biztonságos terhelési út, kommunikáció és szükséges akadályok.","Egy embernek kell utat mutatnia a teher alatt.","A teherszállítás biztonságos közlekedési útvonalakat és világos koordinációt igényel."],"l2-schutzschlauch":["Mire kell figyelni, ha védőtömlővel ellátott hevedereket használ?","Egy szalag fekszik egy durva élnek.","Bármilyen vékony kendő helyettesíti a megfelelő élvédelmet.","A védőtömlő minden megengedett terhelési határt eltávolít.","Válassza ki a védőfelszerelést az alkalmasság és az alkalmazási követelmények alapján.","A védőfelszerelésnek meg kell felelnie az anyagnak, a szélnek és a tervezett terhelésnek."],"l2-reinigung":["Egy emelőheveder ismeretlen vegyszerrel volt szennyezett. Mi a helyes?","A szalagot már nem lehet egyértelműen értékelni.","Hagyja abba a használatát, és szakszerűen tisztázza a kompatibilitást vagy állapotot.","Tisztítsa meg bármilyen oldószerrel, és azonnal folytassa az emelést.","Hagyja figyelmen kívül a vegyszert, amíg a szalag száraz.","A vegyszerek befolyásolhatják a textilhevederek szilárdságát."],"l2-aufhaengung":["Mit ellenőriz, hogy nincs-e több szál a felfüggesztő linken?","Két szálat egy szuszpenzióba helyeznek össze.","Egy szál tetszőlegesen beköltözhet a horog hegyébe.","Minden összekötő elemnek megfelelőnek és rendeltetésszerű elrendezésnek kell lennie.","A repedéses gyűrű kis terhelésekhez használható.","Az ütköző- és csatlakozóelemeknek teherbírónak és megfelelően elhelyezettnek kell lenniük."],"l2-einweiserrolle":["Mi a helyzet, ha a támadónak és a darukezelőnek nincs rálátása?","Egy hordozó blokkolja a leadási pont kilátását.","Koordináljon több személy felhívásával felelősség nélkül.","Mozgassa a terhelést a zaj alapján, utasítás nélkül.","Szervezze meg az egyértelmű, biztonságos kommunikációt, és állítsa le, ha nem egyértelmű.","A láthatóság hiányát hatékony koordinációval és biztonságos kommunikációval kell kompenzálni."],"l2-ausserbetrieb":["A sérült hevedert rendbe hozták. Mi még fontos?","Szabadon hozzáférhető marad a használatra kész források mellett.","Biztosítsa a további véletlenszerű használat ellen, és értesítse a felelős személyt.","A terméket jelölés nélkül küldje vissza a készletbe.","Csak akkor használja újra, ha különösen könnyű terhet szállít.","A kiselejtezett hevedereket további használat előtt megbízhatóan védeni kell."],"b2-schwenkradius":["Miért kritikus a kotrógép hátsó lengési sugara?","A farok korlátozott munkaterületen mozog.","Harmadik személyeket megfoghat a lengő felépítmény.","A lengési sugár nincs hatással a gép mellett tartózkodó személyekre.","A hátsó mindig csak a menetirányban mozog.","Elforduláskor a gép mögött is kialakul egy veszélyes terület."],"b2-verkehrseinweiser":["Hogyan biztosítható a vezetési mozgás, ha a látási viszonyok homályosak?","A kotrógépnek akadály mögött kell manővereznie.","Vezessen anélkül, hogy látná a jeladó jelzéseit.","Ha szükséges, szervezzen megfelelő oktatást egyértelmű kommunikációval.","Csak egyszeri dudálással biztosítsa a tolatást.","A zavaros útvonalak hatékony intézkedéseket igényelnek az ütközések és a beszorulás megelőzésére."],"b2-standplatz":["Mi vonatkozik a lejtőn lévő kotróállványra?","A padló lejtős és csúszós lehet.","A gép tetszőleges dőlésszög esetén ameddig csak akar.","A kotrógépet mindig laza földrétegre állítsa fel.","Használat előtt ellenőrizze a gép stabilitását és működési határait.","A lejtők lejtése és az altalaj jelentős befolyással bír a stabilitásra."],"b2-oberleitung":["Miért kell megtervezni a gém távolságát a villamos vezetékektől?","A gém elfordításkor közel kerülhet a kábelhez.","Az elektromos átvilágítás közvetlen érintkezés nélkül is lehetséges.","Csak a vödör vezeti az áramot, a gém nem.","Száraz talaj esetén minden távolság automatikusan biztonságos.","Az elektromos rendszerekhez való közeledés előtt tisztázni kell a használati határokat és a védőtávolságokat."],"b2-fremdperson":["Egy járókelő lép be az építkezésre a pásztázási területen. Mi a helyes?","A személy hirtelen a kotrógép kanala közelében áll.","Emelje fel a lapátot, és lendítse át a személyen.","Azonnal hagyja abba a mozgást, és tisztítsa meg a területet.","Csak továbbra is figyelje a személyt az oldalsó ablakból.","A veszélyzónában tartózkodókat munkamozgások nem veszélyeztethetik."],"b2-parkstellung":["Hogyan biztosítható a földmunkagép a munka befejezése után?","A kotrógép felügyelet nélkül marad az építkezésen.","Hagyja a kanalat fejmagasságban.","Hagyja a motort felügyelet nélkül járni.","Tegye le a munkaeszközt, rögzítse a gépet és akadályozza meg az illetéktelen használatot.","A megfelelő parkolás csökkenti a véletlen mozgást és az illetéktelen hozzáférést."],"b2-eigenlast":["Miért fontosak a felszerelési korlátok kotrógéppel történő emeléskor?","A gémre nehéz terhet kell felvenni.","Ellenkező esetben a stabilitás és a megengedett teherbírás túlléphető.","Bármely gép bármilyen terhet fel tud emelni, amíg a vödör elfér.","Csak a hevederkötél hossza határozza meg a kockázatot.","Az emelési és teherbírási információk a berendezéstől és az alkalmazási helyzettől függenek."],"b2-untergrundhohlraum":["A régi pince feletti padló üreges lehet. mit csinálsz?","A kotrógépet be kell vinni a területre.","Maximális lendülettel haladjon át a ponton.","Indulás előtt tisztázza a terhelhetőséget és a lehetséges üregeket.","Egyszerűen helyezzen nagy terhelést a felületre.","Az üregek a gép súlya alatt összeeshetnek, és a gép összeomlását okozhatják."],"b2-feuchtigkeit":["Heves esőzés után a töltés puhává válik. Mi a helyes?","Egy kotrógép dolgozik a töltés széle közelében.","Vigye közelebb a gépet a széléhez, hogy növelje az elérést.","Figyelmen kívül hagyja a változtatásokat a műszak végéig.","Mérje fel újra a talaj- és stabilitási viszonyokat.","A nedvesség behatolása megváltoztathatja a töltések teherbíró képességét és stabilitását."],"b2-bodenprobe":["Miért kell a csővezeték terveket ásatás előtt ellenőrizni?","A kábelek a tervezett feltárás alatt futhatnak.","A vonalak azonosítása és a megfelelő biztonsági intézkedések megtervezése érdekében.","Annak érdekében, hogy a feltárás gyorsabban elvégezhető legyen, függetlenül a harmadik féltől származó rendszerektől.","Mivel a gépeket soha nem szabad kábelek közelében használni.","A föld alatti tápvezetékek megbízható helymeghatározást igényelnek a földmunkák előtt."],"b2-maschinenzugang":["Mi vonatkozik a földmunkagépbe való be- és kiszálláskor?","A gép egyenetlen terepen áll.","Csúsztassa ki a hidraulika vezetéket a fülkéből.","Használja a kijelölt lépéseket, és biztosítson biztonságos támaszt.","A gép működése közben ugorjon a forgókarra.","A biztonságos mászások és a megfelelő megállási pontok csökkentik az esés és zúzódás kockázatát."],"b2-kupplung":["Hogyan kell ellenőrizni az új kotrógépet beszerelés után?","A kanál a gyorscsatlakozón keresztül csatlakozik.","Csak vizuálisan ítélje meg a kanalat nagyobb távolságból.","Lépjen közvetlenül a felemelt kanál alá.","Gondoskodjon a megfelelő zárolásról és az előírt vezérlési lépésekről.","A helytelenül lezárt tartozékok kilazulhatnak, és veszélyeztethetik az embereket."],"b2-hydraulikwartung":["Miért nem szabad nyomás alatt kinyitni a hidraulika vezetékeket?","Cserélni kell egy tömlőt.","A kiáramló folyadék súlyos sérüléseket okozhat a nagy nyomás miatt.","A nyomás mindig megakadályozza az olaj kijutását.","A nyitott vonal biztonságosan ellenőrizhető a kezével.","A nagynyomású folyadék behatolhat a szövetekbe, és biztonságos nyomáscsökkentést igényel."],"b2-fahrweg":["Át kell hajtani egy ideiglenes építési hídon. Mit ellenőriz?","A hidat csak bizonyos terhelésekre tervezték.","A híd színe illeszkedik-e a géphez.","Terhelhetőség és alkalmasság a gép súlyához és méreteihez.","Csak azt, hogy egy könnyű autó hajtott-e már a hídon.","Ideiglenes szerkezetek csak bizonyított teherbíró képességükön belül használhatók."],"b2-baggertransport":["Mi a fontos a kotrógép alacsony rakodógépen történő szállítása során?","A gépet a következő építkezésre viszik.","Hagyja, hogy a munkaeszköz lazán kinyúljon a szélén.","Vezetés közben tartsa nyitva a kabin ajtaját.","Rögzítse a gépet a szállítási előírásoknak megfelelően, és ellenőrizze a rakodóberendezést.","A szállítási zárak és a megfelelő rakodóberendezések megakadályozzák a megcsúszást és leesést."],"b2-schaufelfuellung":["Miért nem engedik, hogy a gumikerekes rakodó gyorsan vezessen magasra emelt kanállal?","A teher nehéz, a talaj pedig egyenetlen.","A magas súlypont növelheti a borulás és a látási problémák kockázatát.","A kanál automatikusan stabilizálódik nagy sebességnél.","A lapát magasságának nincs jelentősége a stabilitás szempontjából.","A megemelt súlypont jellemzően rontja a stabilitást vezetés és kanyarodás közben."],"b2-fussgaenger":["Hogyan viselkedik, amikor gyalogosok mellett manőverez?","Az építkezés bejárata egyben gyalogút is.","Használja a lapátot, hogy oldalra irányítsa a gyalogosokat.","Csak akkor hajtsa végre a vezetési mozgást, ha a terület biztonságosan szabad és kezelhető.","Csak dudáljon egyszer, és lassan haladjon tovább láthatóság nélkül.","A jármű- és személyforgalmat hatékonyan el kell választani, vagy biztonságosan össze kell hangolni."],"b2-ueberlastwarnung":["Emeléskor a gép túlterhelést jelez. mit csinálsz?","A felemelt rakomány eléri a megengedett határértékeket.","Kapcsolja ki a figyelmeztetést, és változatlanul emelje fel.","A gép működése közben hirtelen húzza meg a terhet.","Állítsa le a veszélyes mozgásokat és javítsa biztonságosan a terhelési helyzetet.","A túlterhelési figyelmeztetések a határértékek lehetséges megsértésére és a stabilitási kockázatokra utalnak."],"b2-wasserleitung":["Ásás közben egy ismeretlen cső kerül elő. Mi vonatkozik rá?","A vonal nem szerepel a kiviteli tervekben.","Állítsa le a munkát az érintett területen, és szakszerűen azonosítsa be a vonalat.","Próbálja mozgatni a zsinórt a kotrólapáttal.","Folytassa az ásást közvetlenül a zsinór alatt, ellenőrzés nélkül.","Az ismeretlen vezetékek elektromos, gáz- vagy vízveszélyt okozhatnak."],"b2-hangefahrt":["Hogyan kell vezetni egy kotrógépet meredek lejtőn?","A tervezett útvonal lejtőn vezet.","Vezessen át a lejtőn, tekintet nélkül a gyártó korlátaira.","Tartsa be a gép megengedett dőlésszögét és előírt vezetési stílusát.","Hajtsa ki a gémet, hogy egyensúlyba hozza a járművet.","A megengedett lejtés a géptől, a felülettől és a gyártó információitól függ."],"b2-schlechtebeleuchtung":["Sötét gödörben végzett munka során a látási viszonyok nem megfelelőek. Mi a helyes?","Alig látsz embereket és akadályokat.","Növelje az ásási sebességet a művelet gyors befejezéséhez.","Járó motor mellett ne használja a lámpákat.","Állítsa le a munkát, amíg a veszélyes területek kellően láthatóvá nem válnak.","A vezetési és munkaterületek biztonságos láthatósága szükséges az ellenőrzött gépmozgáshoz."],"b2-kettenverschleiss":["A napi ellenőrzés során sérült hernyónyomot észlelnek. mit csinálsz?","A lánccsatlakozás egyértelmű sérülést mutat.","Ne használja tovább a gépet ellenőrizetlenül, és jelentse a sérüléseket.","Haladjon tovább nagy sebességgel, hogy a lánc kiegyenesedjen.","Csak puha talajon folytassa a munkát ellenőrzés nélkül.","A meghajtó károsodása ronthatja a kezelhetőséget és a stabilitást."],"b2-ladearbeiten":["Felraksz egy teherautót a kotróval. Mi a fontos?","A teherautó-sofőr a rakodótér közelében marad.","Hajtsa át a vödröt a védtelen vezetőfülke fölé.","Akadályozza meg, hogy emberek tartózkodjanak a veszélyes területen, és koordinálja a folyamatokat.","Indítsa el a betöltést anélkül, hogy kommunikálna a vezetővel.","Rakodáskor fennáll az anyag leesésének és a lengő mozgások veszélye."],"b2-arbeitsunterbrechung":["Megszakítja az ásatást egy értekezlet miatt. Mi vonatkozik rá?","A gépnek néhány percig állnia kell működés nélkül.","Hagyja meg a felemelt lapátot jelölőnek.","Hagyja a gépet felügyelet nélkül bekapcsolt vonóhajtás mellett.","Helyezze le biztonságosan a munkagépet, és biztosítsa a gépet véletlen használat ellen.","Még a rövid megszakítások is biztonságos gépállapotot igényelnek."],"b2-rollmaterial":["A laza anyag leeshet a kerekes rakodóval történő szállításkor. Mi a helyes?","A rakodó az alkalmazottak közelében halad.","Biztonságosan vegye fel a terhet, és válasszon biztonságos vezetési stílust megfelelő lapátpozícióval.","Emelje fel a lapátot a lehető legmagasabbra, hogy a környező terület jól látható legyen.","Vegye fel a rakományt a vödör töltésének korlátozása nélkül.","A laza rakományok, a kanál magas helyzete és a rossz látási viszonyok veszélyeztethetik az embereket és a forgalmat."]};
